quests[14410] = { id = 14410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wilds of Feralas", description = "You are truly brave to help us protect these lands, hero. If you wish to do more for the wilds, there are others in need of your aid.\n\nThe verdant forests of Feralas lie to the south. There, in the shade of the mighty Twin Colossals, you must seek out Telaron Windflight. At Dreamer's Rest, he and his fellow druids of the talon have found signs of a disturbing illness.\n\nThey will need your help, {class}. Go in peace.", sourceObjective = "Travel to Feralas and speak with Telaron Windflight at Dreamer's Rest.", completion = "Welcome to Feralas, {class}. I thank you for coming to assist us.", sourceObjectiveStatus = "unverified-source-field" }
quests[14412] = { id = 14412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Washed Up", description = "Those Forsaken ships sank way too close to our Fishery.  All the survivors are making their way here and, as you can see, we're a bit outnumbered.\n\nHelp us hold them back while I finish making repairs to the boats.", sourceObjective = "Kill 6 Forsaken Castaways.", progress = "Bloody Forsaken!  Not even the ocean wants them!", completion = "Excellent!  I'm almost done here.", sourceObjectiveStatus = "unverified-source-field" }
quests[14413] = { id = 14413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pinnacle of Learning", description = "This is so exciting! What's exciting you might ask? Well THIS is of course!\n\nTime to trial... time for YOU to trial. So many challenges to overcome, so much learning to be done. You learning about trials. Me learning about you.\n\nSo now, off you go. To my Arcane Pinnacle. I will meet you there of course, because I'm quite everywhere.", sourceObjective = "Speak to the Image of Archmage Xylem at the base of the Arcane Pinnacle.", completion = "Here so soon! Lovely trip I hope. Not too nauseous or anything?\n\nThere will be much running and much jumping, so a settled stomach is of great practicality.", sourceObjectiveStatus = "unverified-source-field" }
quests[14416] = { id = 14416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hungry Ettin", description = "Listen, {name}.  We're not going to make it very far without transportation, are we?\n\nIf we just hightail it out of here, the forsaken will catch up to us in no time at all.\n\nRounding up some horses from the stable grounds southeast of here would normally be a breeze, but there's one snag.\n\nThat last quake must've spooked Koroth, the ettin, down from the mountains.  If we don't get our horses soon, I fear that he will.", sourceObjective = "Bring 5 Mountain Horses to Lorna Crowley at the Crowley Orchard.", progress = "You're back, {name}.", completion = "We've got the horses, I'll make sure Duskhaven gets them.", sourceObjectiveStatus = "unverified-source-field" }
quests[14418] = { id = 14418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deathstalkers", description = "The Syndicate? I would never have suspected. It seems the lords of Alterac have fallen far in the years since their betrayal.\n\nHawkins will be pleased to learn of this, and as you were so instrumental in this discovery, it would be fitting if you were the one to deliver it to him.\n\nAh, and how could I forget?\n\nWelcome to the Deathstalkers.", sourceObjective = "Deliver Andron's Ledger to Aleric Hawkins in the Hall of the Dark Lady in the Undercity.", progress = "Yes?", completion = "Hmm, this is interesting. The Deathstalkers have performed their duties admirably in ferreting this out.\n\nAs I'm told, you deserve a reward for your part in these matters. Keep this up, {name}; the Deathstalkers always have use of a good man.", sourceObjectiveStatus = "unverified-source-field" }
quests[14419] = { id = 14419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deathstalkers", description = "The letter of introduction should be enough to convince Andron that you are the messenger he's been waiting for. I've met Andron before, he doesn't quite have the mental capacity to be that suspicious.\n\nOur leader suspects that Andron has been providing aid to some other group. He wishes to know what organization this is and requires proof of it.\n\nI want you to speak with Andron, and obtain this information. You'll find him at his shop near the Apothecarium.", sourceObjective = "Speak with Andron Gant in the Undercity.", progress = "Hello. Something I can do for you?", completion = "Ah, yes, I've been expecting you. I have no doubt our mutual acquaintances are pleased with the information that I have provided so far?\n\nI suppose there's no point in asking you, I doubt they would burden you with this knowledge. Why place so much trust in the messenger, hm?", sourceObjectiveStatus = "unverified-source-field" }
quests[14420] = { id = 14420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deathstalkers", description = "If you wish to join the Deathstalkers, the Dark Lady's elite guard, you will have to prove your worth.\n\nI will not lie to you, {name}, this task could mean your death.\n\nI have some things that need attending to. I require the personal effects of Astor Hadren, a messenger who travels between Silverpine and the Undercity. I will leave the method of procurement to your discretion.\n\nIt will be better for you if you know less of the nature of this business. Succeed and I shall tell you more.", sourceObjective = "Get Astor's Letter of Introduction and return it to Mennet Carkad in the Rogues' Quarter.", progress = "Success to report?", completion = "Well done, {name}. You've passed the first part of this test. Hopefully Andron will not have caught wind of your activities, and we will be able to convince him that you are, in fact, the messenger he is expecting.", sourceObjectiveStatus = "unverified-source-field" }
quests[14421] = { id = 14421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deathstalkers", description = "You'll find the ledger with the information your employers seek on the bookshelf behind me. Deliver it with my regards, and tell them that I would prefer it if they sent you, if they find enough value that they should wish to continue our arrangement.", sourceObjective = "Bring Andron's Ledger to Mennet Carkad in the Rogues' Quarter of Undercity.", progress = "Success, {name}?", completion = "Well, this is certainly more information than I suspected to get out of Andron. Give me a moment to peruse it, before I set you to your next task.", sourceObjectiveStatus = "unverified-source-field" }
quests[14422] = { id = 14422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptor Raptor Rocket", description = "Shortly after my intellect was augmented, I bred with Subject Four in order to create a unique race of cognitively superior raptors. Subsequently, Subject Four neither called nor wrote: I have determined to disembowel him upon our next encounter.\n\nNonetheless, there are enough raptor children imprisoned in this lab to provide adequate genetic stock for repopulating my race. Please release them from their cages and carry them to the rocket.", sourceObjective = "Release five Experimental Raptors from their cages in the Secret Lab and deliver them to the rocket beside Subject Nine.", progress = "My beautiful children may attempt to bite you upon release, but at their stage of physical development, it is unlikely that their attacks will be fatal.", completion = "Wonderful! Exemplary work, {name}! As you have no doubt surmised, my objective with regard to this rocket is to utilize it as a sort of astral cradle, an ark if you will, allowing my newly-forged race to slip the surly bonds of this ravaged planet and colonize a world to our own liking. You have been instrumental to our cause. Please accept this currency as I will be minting my own monetary units upon arrival. Farewell, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[14423] = { id = 14423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dozercism", description = "...what we need is a priest!\n\nFortunately I have a small budget set aside for the blessing of machinery. Take this flare gun and head over to Margene, my poor sweet busted bulldozer. Fire off the signal and one of our finest airborne priests should airdrop in to get a handle on the situation. Come back when my bulldozer is taken care of!", sourceObjective = "Use the Blessed Flare Gun near Clubnik's Dozer to summon in help, then 'Exorcise' the bulldozer.", progress = "How is Margene doin'? Running like her sweet self again?", completion = "What? ...What?\n\nMargene! Oh my sweet Margene!!", sourceObjectiveStatus = "unverified-source-field" }
quests[14424] = { id = 14424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Need More Science", description = "<Clubnik wipes away a tear, then juts his chin out with determination.>\n\nNever again, {name}! No bulldozer deserves the fate of my Margene. We're going to need some industrial ghostproofing. This is a job for our top scientists, and I know just the woman for the job! Look for Assistant Greely at the Southern Rocketway Terminus. She's the administrator for Azshara's world-famous Secret Lab, and she owes me a favor.", sourceObjective = "Locate Assistant Greely at the Southern Rocketway Terminus. The Goblin Rocketway can be used to quickly move around Azshara.", completion = "What is Clubnik talking about? Haunted construction equipment? Does it look like I have time for ghost stories?\n\nI've got a laboratory in the middle of a meltdown, fires burning, animals mutated, and worst of all - projects falling behind schedule. Help!", sourceObjectiveStatus = "unverified-source-field" }
quests[14427] = { id = 14427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Item Quest", description = "Item collection quest", sourceObjective = "Get the items", sourceObjectiveStatus = "unverified-source-field" }
quests[14428] = { id = 14428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amberwind's Journal", description = "If my sources are trustworthy, Lorekeeper Amberwind is overseeing the Alliance investigation of the ruins to the east. I have not yet probed the extent of her abilities: I'm hoping you can give me a full report by engaging her in combat and destroying her.\n\nWith a title like 'Lorekeeper,' I'm guessing Amberwind will have a journal on her that'll tell us exactly what those night elves are up to. Fetch that journal for me. No need to run back; use their own scrying stones to contact me remotely.", sourceObjective = "Slay Lorekeeper Amberwind at the Darnassian Base Camp and retrieve her journal.", progress = "<Andorel's distorted face appears within the scrying stone.>\n\n{name}, have you made contact? What can you tell me?", completion = "Amberwind was making use of an Arcane Construct? Hah! How delightfully inexperienced. It's like watching children play with firearms.\n\nLet's take a look at that journal, {name}. Hold it up to the scrying stone... keep it still ...", sourceObjectiveStatus = "unverified-source-field" }
quests[14429] = { id = 14429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane De-Construction", description = "Arcane constructs are creatures spawned of pure mana and intellect. In the right hands, a construct allows its user to quickly assimilate vast riches of arcane knowledge. But they're dangerous, {name}. So intelligent! So powerful! So very vulnerable to external tampering...\n\nLet's teach these amateurs a lesson and use their own magic against them. Slay Apprentices and collect their runestones for me. Contact me via the lower scrying stone when you're done.", sourceObjective = "Slay Apprentice Investigators and Apprentice Illuminators to collect 10 Attuned Runestones.", progress = "<Andorel's image is blurry and indistinct. He squints at you and taps against the glass of the scrying stone.>\n\n{name}, is that you? The resolution on this stone is terrible. What kind of hardware are they using?", completion = "Good work getting those runestones. To be honest, I only needed one, but the thought of so many night elves slain for such useless baubles fills me with a dark, giddy joy.\n\nPlease hold one of those runes up to the scrying stone to let me see. Hmmm. As I suspected, an amateur effort at best.", sourceObjectiveStatus = "unverified-source-field" }
quests[14430] = { id = 14430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hacking the Construct", description = "Now we will hack their arcane construct and use it to wreak havoc. Have you done this type of magic before, {name}? No? Hah! That makes my plan all the more delicious. Nearby you should see a formidable arcane construct they've summoned. Thanks to the runestones you gathered, we know how to communicate with it. Talk to the construct and say \"Al'teth la c'tolgar.\" Got that? Repeat it? Close enough. Report back to me and let me know what happens!", sourceObjective = "Speak with the Arcane Construct at the Darnassian Base Camp and utter the words of arcane power.", progress = "Did it work? Tell me everything! Describe the looks on their faces!", completion = "Haha! Hah - HA! Night elf \"mages\" fleeing their own arcane creation. Your actions have made my month, {name}. That's why we blood elves don't use arcane constructs anymore - they've been outlawed for, oh, 1500 years. It's amusing to me to watch our foes repeat the mistakes of the past. \"Mages.\" Indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[14431] = { id = 14431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blackmaw Scar", description = "The Blackmaw furbolg that live in this area have broken rank with their Timbermaw brethren as we began to aggressively settle Azshara. They've gone wild, {class}, and harass our forces at every turn. Worse, we have seen them engaging the night elves from Talrendis on friendly terms. We cannot allow the two to ally!\n\nJust southwest of here you will find a great scar across the earth where my scouts report night elven activity. Slay them and gather any intelligence you find.", sourceObjective = "Slay 8 Talrendis Biologists and gather up Blackmaw Intelligence from one of the bodies.", progress = "The Blackmaw are ferocious. Were they ever to organize, they would prove to be an immense disruption to our work here.", completion = "I see... This definitely looks like a working draft of some sort of treaty. That's a worst-case scenario for us, {name}: Night elves coordinating attacks with entrenched furbolg allies.\n\nMy initial instinct - a full-out frontal assault - would only drive them into the arms of the Alliance. We will have to take a different approach...", sourceObjectiveStatus = "unverified-source-field" }
quests[14432] = { id = 14432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pale Brew", description = "It looks like our Alliance foes have been making headway with their Blackmaw talks by conducting negotiations in the furbolg tongue. If we're to sabotage the treaty, we're going to have to do the same.\n\nIt's not as hard as it sounds, {name}. The Blackmaw make a potent herbal tea, the fumes of which will place one in a trance-like state where you'll start speaking in tongues. The Blackmaw tongue, specifically. Go to Blackmaw Hold southwest of here and get me some samples of that briaroot brew!", sourceObjective = "Gather up 10 samples of Briaroot Brew from outside Blackmaw Hold.", progress = "How goes the hunt? I sampled that briaroot stuff myself once, but it was too bitter, even for an old gravel-eater like myself.", completion = "Ah good, that's plenty. We'll boil this stuff up and you can bask in the fumes for a while - you'll be speaking like a furbolg in no time. Our plan is beginning to take shape...", sourceObjectiveStatus = "unverified-source-field" }
quests[14433] = { id = 14433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomacy by Another Means", description = "In order to infiltrate and disrupt the Blackmaw negotiations, we'll need to know where they're happening. In Blackmaw Hold to the southwest, I suspect you'll find night elven ambassadors milling around, making preparations.\n\n<Haggrum spits on the ground.>\n\nKill them at your leisure, and search the area for important documents. Oh, and grab a set of their ambassador's robes, we'll need them.", sourceObjective = "Gather a Blackmaw Meeting Agenda at Blackmaw Hold, and kill a Talrendis Ambassador to collect her Ambassador's Robes.", progress = "Do you have the robes? Andorel here has been whipping up some magic for us to use.", completion = "Excellent work! Let me see those documents. Hmm. Now we know exactly when and where the final negotiations will happen. Don't worry if those robes don't fit you - I've got it all worked out.", sourceObjectiveStatus = "unverified-source-field" }
quests[14434] = { id = 14434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rut'theran Village", sourceObjective = "Are you ready to set sail, {name}?  Your people have been granted shelter in the lands of the kaldorei.\n\nDo not worry, {race}.  Your people will get a chance to fight for Gilneas again.  This time, with the full strength of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[14435] = { id = 14435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blackmaw Doublecross", description = "Andorel here has crafted a little bit of magic for me. Come, stand next to my fire, and steep yourself in the fumes from the tea. Drape the robes around you and you'll take on the appearance of a night elven ambassador to the Blackmaw.\n\nDon your disguise and speak to Andorel here in camp. He'll teleport you to the heart of Blackmaw hold, where the negotiations are to take place. Speak with Chieftain Ungarl and sabotage the treaty. Then, kill as many Blackmaw as you can on the way back!", sourceObjective = "Wear the Ambassador Disguise and talk to Andorel Sunsworn to teleport into Blackmaw Hold. Speak with Ungarl to wreck the negotiations, then kill 4 Blackmaw Warriors and 4 Blackmaw Shaman on your way out.", progress = "If our ruse pays off, {name}, we will forever drive a wedge between the Alliance and the Blackmaw.", completion = "Victory! The Blackmaw won't know who to trust anymore.\n\nWith that delicate bit of business complete, I can orchestrate a full-on assault against those beasts without worrying about them siding with the Alliance.\n\nYou do good work, {name}. Perhaps we should place you in the Horde diplomatic corps? Hah-har!", sourceObjectiveStatus = "unverified-source-field" }
quests[14436] = { id = 14436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dwarven Digging", description = "There are dwarves preparing a dig site to the northwest.  They think secrets lie in the earth, and that is true, but hollowing and defiling the land is no way to earn its teachings.\n\nCollect the dwarven tools of digging, smash them, and return to me with the dwarves' broken tools.\n\nYou can smash the tools at a forge.  You will find one in Thunder Bluff, but any forge -- even a forge at the dwarven camp -- will suffice.You will be able to choose one of these rewards:", sourceObjective = "Collect 5 Prospector's Picks.\n\nAt a forge, smash the Prospector's Picks to create Broken Tools.\n\nBring 5 Broken Tools to Ahmo Thunderhorn in Bloodhoof Village.", sourceObjectiveStatus = "unverified-source-field" }
quests[14437] = { id = 14437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rites of the Earthmother", description = "For you to continue with the Rites of the Earthmother you must pass two more tests. It is time for you to broaden your experience, {name}.\n\nTravel to Bloodhoof Village and seek out the Ahmo Thunderhorn. There you may continue your journey and earn the acceptance of the elders of Thunder Bluff.\n\nTake this totem to Ahmo. He will recognize my carvings and help you on your path.\n\nFollow the road out of Camp Narache and travel with haste. Do not stray or you will lose your way.", sourceObjective = "Take the Totem of Hawkwind to Ahmo Thunderhorn in Bloodhoof Village. Follow the road out of Camp Narache.", sourceObjectiveStatus = "unverified-source-field" }
quests[14438] = { id = 14438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharing the Land", description = "{name}, there are many conflicts that wound this land. It is my hope that you will not bear witness to as many of them as our elders have. Yet there is one that I would ask you to seek. It will give you some sense of how terrible, if left unchecked, even a small threat can be to the land.\n\nPalemane gnolls have settled to the south of Bloodhoof and in a cave to the west. They disrespect our attempts to communicate with them, and they slay the wildlife of Mulgore unbridled.\n\nWords are no longer the answer.", sourceObjective = "Kill 15 Palemane Gnolls then return to Ahmo Thunderhorn in Bloodhoof Village.", progress = "If the Palemanes had respected the land and its inhabitants more, this conflict would have never occurred.", completion = "{name}, it is good you've taken the task seriously. Respect of the land and its creatures is important. Death and life are a circle... a necessity. One cannot exist without the other. Take time to ponder this and do well to never forget it.", sourceObjectiveStatus = "unverified-source-field" }
quests[14439] = { id = 14439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey into Thunder Bluff", description = "You will now be revered within our great city. Any {race} worthy of completing the Rites of the Earthmother earns that honor.\n\nFor your final quest, seek out our young leader, Baine Bloodhoof, who dwells atop the highest mesa in Thunder Bluff.", sourceObjective = "Speak with Baine Bloodhoof in Thunder Bluff.", sourceObjectiveStatus = "unverified-source-field" }
quests[14440] = { id = 14440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rites of the Earthmother", description = "You have passed the Rites of the Earthmother and earned your place in Thunder Bluff.\n\nBut in order to maintain the spot that you strived so hard to achieve, you must continue to prove your worth to your people.\n\nWe are hunters, {name}. Down below in Mulgore there is a mighty kodo named Arra'chea. Show me your skills in the ways of tracking and hunting by bringing me the Horn of Arra'chea.", sourceObjective = "Baine Bloodhoof in Thunder Bluff wants you to bring him the Horn of Arra'chea.", sourceObjectiveStatus = "unverified-source-field" }
quests[14441] = { id = 14441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrosh's Autograph", description = "They say that Garrosh Hellscream is one of the greatest heroes in the Horde! When I grow up, I want to be a hero of the Horde too!\n\nDo you know Garrosh, {name}? Could you do me a favor, please? Could you get his autograph for me? I dunno how to ask him, and he probably wouldn't listen to someone like me... but you! You're an adventurer, like him! I bet he'd give you his autograph easy!\n\nPlease?", sourceObjective = "Travel to Orgrimmar to see about getting Garrosh Hellscream's autograph for your ward.", sourceObjectiveStatus = "unverified-source-field" }
quests[14442] = { id = 14442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Favorite Subject", description = "I don't know if you've noticed {name}, but this whole lab complex has gone south of cheese! I don't mind writing off all those hippogryphs, but my most prized experiment has gone missing: Subject Nine!\n\nSubject Nine is a raptor we imported from the Barrens. I wonder - is she still alive? Try checking above the main complex west of here, near the giant top secret rocket. You can't miss it.", sourceObjective = "Locate Subject Nine somewhere near the Secret Lab complex in Azshara.", completion = "Have you come to assist me with my work? My claws are quite dexterous, but I must reluctantly confess that my arms are debilitatingly short.", sourceObjectiveStatus = "unverified-source-field" }
quests[14443] = { id = 14443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battered Hilt", description = "This battered old sword hilt has seen better days. Before the hilt was snapped from the blade, it must've been a magnificent example of the blacksmith's art.\n\nThe graceful symbols and exotic gemstones decorating the hilt suggest that the weapon may have belonged to a powerful person. Surely, the Silver Covenant members would be interested in hearing about the recovery of such an artifact. Seek out their representative at Quel'Delar's Rest, south of the Argent Tournament Grounds.", sourceObjective = "Bring the Battered Hilt to Caladis Brightspear at Quel'Delar's rest, south of the Argent Tournament Grounds.", progress = "What is it that you have there?", completion = "<Caladis takes the hilt from you and slowly turns it over in his hands.>\n\nThis seems somehow familiar, as though I should know its origins. You say you recovered this in the citadel? Most intriguing.\n\nThere are few who possess the ability to make such a blade. Perhaps they can tell us something about your find.", sourceObjectiveStatus = "unverified-source-field" }
quests[14444] = { id = 14444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What The Dragons Know", description = "There's no mistaking it - this hilt comes from a powerful, ancient weapon, but which one? I do not recall seeing or hearing of a sword with these markings, but that doesn't mean that all is lost.\n\nKorialstrasz, better known as Krasus, has long been a friend to the quel'dorei and the Kirin Tor. With his vast knowledge and resources, he's certain to know something. Travel to the top of Wyrmrest Temple and seek his counsel, then report to Arcanist Tybalin inside the Silver Enclave in Dalaran.", sourceObjective = "Speak to Krasus at the top of Wyrmrest Temple.", completion = "We can't let that book remain in Sunreaver hands. If we hope to identify the sword and use it to our advantage, we have to find a way to capture the book Krasus lent them.", sourceObjectiveStatus = "unverified-source-field" }
quests[14445] = { id = 14445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farewell, For Now", description = "Our destinies are forever intertwined. There are events taking place that are reshaping our world and ultimately will destroy it. We must put an end to them before it is too late.\n\nKnow that you can always count on me, <brother/sister>! We will meet again on the larger island. May you find peace until then, {name}.", sourceObjective = "Speak with Sassy Hardwrench at the Wild Overlook on the Lost Isles.", completion = "Wow, oh wow! Is that who I think it is?\n\nYou rescued Thrall, Warchief of the Horde?!!!\n\n<Sassy gives you an appraising look.>\n\nWell, let's see about getting over to that larger island. I sure as heck don't want to swim the strait with all of those sharks down there.", sourceObjectiveStatus = "unverified-source-field" }
quests[14446] = { id = 14446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cataclysm!", description = "Hear my words, {class}!\n\nThe winds of change have gathered into a violent storm that sweeps across Azeroth.\n\nHave you the courage to face the true cause of our plight?\n\nMuster your resolve, {race}, and pray for the strength and fortune to see you through the trials that await.\n\nAn unexpected ally has issued a call for all that would hear. Peer into the Waters of Farseeing and behold the fate of the world!", sourceObjective = "Nambria wants you to peer into the Waters of Farseeing.", sourceObjectiveStatus = "unverified-source-field" }
quests[14447] = { id = 14447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Takes One to Know One", description = "While we should never miss an opportunity to strike out against the Alliance, we mustn't forget about the Scourge.\n\nWe won't have the numbers here to make a proper assault in the glacier for weeks, but that won't keep us from learning all we can know about their defenses.\n\nI have asked our resident death knight to advise you in this effort. After all, who better knows this enemy than they?\n\nAllow me to introduce Koltira Deathweaver.", sourceObjective = "Sky-Reaver Korm wants you to speak to Koltira Deathweaver on Orgrim's Hammer.", sourceObjectiveStatus = "unverified-source-field" }
quests[14448] = { id = 14448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Takes One to Know One", description = "While we should never miss an opportunity to strike out against the Alliance, we mustn't forget about the Scourge.\n\nWe won't have the numbers here to make a proper assault in the glacier for weeks, but that won't keep us from learning all we can know about their defenses.\n\nI have asked our resident death knight to advise you in this effort. After all, who better knows this enemy than they?\n\nAllow me to introduce Koltira Deathweaver.", sourceObjective = "Sky-Reaver Korm wants you to speak to Koltira Deathweaver on Orgrim's Hammer.", sourceObjectiveStatus = "unverified-source-field" }
quests[14449] = { id = 14449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First Step", description = "What you see here is the work of the quilboar, young one. Year after year they have encroached on our village. The great cataclysm finally drove them from their dens to spread like locusts across the land, and now you see the result; my own mother, dead from their savagery.\n\nToday, you are of age. Today, you will take up your weapon and fight for the tribe, and avenge the Greatmother. Follow the path to the east, and find my son, Grull. He will lead you in our strike against the quilboar.", sourceObjective = "Follow the path East out of Camp Narache and find Grull Hawkwind.", completion = "Welcome to your first true test as a {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14450] = { id = 14450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Random Drop Test Progressive", description = "This quest tests random drops with progressive drop percentage.", sourceObjective = "Get 10 Progressive Widgets.", sourceObjectiveStatus = "unverified-source-field" }
quests[14451] = { id = 14451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Random Drop Flat Rate", description = "This quest tests random drops with flat rate drop percentage.", sourceObjective = "Get 10 Flat Widgets.", sourceObjectiveStatus = "unverified-source-field" }
quests[14452] = { id = 14452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rite of Strength", description = "Behold, {name}. The very presence of the Bristleback is a blight. Nothing is left in their wake but corpses and barren land. Camp Narache could become what we see here in but a few days, unless we stand and fight.\n\nThis will be your Rite of Strength; the first ceremony of a tauren brave. Go into the heart of the thornsnarl and kill Bristleback quilboar, then return to me.", sourceObjective = "Kill 6 Bristleback Invaders.", progress = "Get in there, {name}! We won't let any past. I want you in the midst of them, scattering them left and right!", completion = "You've fought well, {name}. We may yet be saved.", sourceObjectiveStatus = "unverified-source-field" }
quests[14454] = { id = 14454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captured Warrior", description = "The quilboar have not only razed our buildings, but have taken tauren captives. I saw them take Brave Sharphorn, a young warrior trainer of ours, away in one of their foul cages.  Please, find a key on one of the quilboar's bodies and go save him!", sourceObjective = "Obtain a Crude Key from one of the Bristleback Quilboar, and use it to unlock the Quilboar Cage holding Brave Sharphorn.", sourceObjectiveStatus = "unverified-source-field" }
quests[14455] = { id = 14455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Thorncallers", description = "Knowing the ways of your prey is another aspect of the hunt. In the lands they come from, quilboar live in the shade and protection of huge thorned roots. When they move, their shamans seed and grow new roots for them to live in.\n\nThese thorns mar the land and choke out other life, turning the earth around them barren.  Go to the south and stop these thorncallers before they have a chance to continue, {name}.", sourceObjective = "Kill 7 Bristleback Thorncallers.", completion = "With the corruptors slain, the Earth Mother will mend her own wounds in due time.  The roots are not meant to thrive here, and will wither.  Balance will return.", sourceObjectiveStatus = "unverified-source-field" }
quests[14456] = { id = 14456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rite of Courage", description = "One of the first lessons you should learn, {name}, is to never underestimate your prey.\n\nWhile we were distracted by the attack on Camp Narache, more of the Bristleback swept in unnoticed and stole a cache of our rifles. You can see them to the south now, filling the air with lead.\n\nThis is your Rite of Courage: brave the hail of gunfire, hunt the Bristleback gun thieves, and bring back our rifles.", sourceObjective = "Recover 7 Stolen Rifles from Bristleback Gun Thieves.", progress = "How many have you brought me, initiate?", completion = "Well done, {name}. Respect your prey, and the danger it carries, but never fear it. In fear, you become prey yourself.", sourceObjectiveStatus = "unverified-source-field" }
quests[14457] = { id = 14457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sunreaver Plan", description = "One of my contacts in the Underbelly caught sight of a Sunreaver agent buying reagents from a dealer in the Black Market area. The Sunreavers normally aren't known for their interest in what goes on down in the sewers, so that's a big indication that they're planning something.\n\nHead into the Underbelly, find this Sunreaver agent, and take care of him. Search the body for any information that might give us a lead on the location of that tome from Wyrmrest. We can't let them get it back to Icecrown first.", sourceObjective = "Obtain the Sunreaver Orders.", progress = "Did you find anything of use on that agent?", completion = "<Arcanist Tybalin examines the captured orders.>\n\nThe agent you intercepted was supposed to transport the Wyrmrest Tome to Icecrown, after meeting with one Magister Hathorel in Sunreaver's Sanctuary. We have to get that book, {name}, and this is our chance. It's not going to be easy, though.", sourceObjectiveStatus = "unverified-source-field" }
quests[14458] = { id = 14458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go to Adana", description = "We've struck a great blow against the quilboar here. I will stay here, and hold the line, but you need to move on.\n\nSeek Adana Thunderhorn; she has taken a few braves to the southwest to root out the rest of the Bristleback.", sourceObjective = "Go to Adana Thunderhorn to the Southwest.", completion = "More trials lay ahead, {name}. I hope you're prepared.", sourceObjectiveStatus = "unverified-source-field" }
quests[14459] = { id = 14459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battleboars", description = "There are more threats to be dealt with here.  The Bristleback are taming wild boars to be used against us.\n\nThese armored battleboars have been abused beyond hope of recovery; they must be put down, for our safety and their peace.  Go to the pens to the south and slay them, {name}. Return to me afterwards.", sourceObjective = "Kill 10 Armored Battleboars.", completion = "Good work, {name}.  Those beasts could have been a greater threat than the quilboar themselves, if we had not taken action now.", sourceObjectiveStatus = "unverified-source-field" }
quests[14460] = { id = 14460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rite of Honor", description = "Chief Squealer Thornmantle leads these quilboar. It was he that set upon Greatmother Hawkwind and took her life, leading the attack on Camp Narache. He fled and hid afterwards, but we've found him. He lurks to the west within his foul den of thorns, fending off any braves we send in after him.\n\nYou've proven yourself as a brave defender of our people, {name}. Kill Thornmantle and bring his mane back to Chief Hawkwind, in honor of our Greatmother!", sourceObjective = "Kill Chief Squealer Thornmantle.", progress = "Have you completed your trials, young one?", completion = "<Chief Hawkwind holds the mane of Thornmantle over his head.>\n\nThe Chief of the Bristleback is slain. Greatmother Hawkwind's spirit has been avenged!", sourceObjectiveStatus = "unverified-source-field" }
quests[14461] = { id = 14461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feed of Evil", description = "We must do more than simply hunt boars here. The eyesore that has been left upon the land must be purged.\n\nTo give them a wild thirst for blood, the battleboars are force-fed raw flesh. Take this torch, and use it to burn the troughs of meat and gore to cinders.", sourceObjective = "Use Adana's Torch to set fire to all 3 Troughs in the Battleboar Pens.", completion = "You've not only wiped the boar pens clean, but put a stop to a horrible desecration.  Well done.", sourceObjectiveStatus = "unverified-source-field" }
quests[14462] = { id = 14462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where's My Head?", description = "He's here, {name}! Captain Grunwald is a high-ranking Alliance officer from Northwatch Hold, no doubt here to coordinate an assault on Orgrimmar with his night elven allies. We have observed him entering the tower southwest of here. I want his head, {class}. I want to send it back to Northwatch to drive a wedge between our enemies!\n\nI've sent a goblin assassin, Slinky Sharpshiv, to the tower but she hasn't returned. Go find her. And get me that head!", sourceObjective = "You've been sent to meet with the goblin assassin Slinky Sharpshiv at the base of the northern tower of Talrendis Point.", completion = "You're just in time, {class}. I'm about to launch a lightning-strike precision assassination. Let's see...\n\nExplosives? Check.\nPneumatic grapplestabber? Check.\nPortable parachute? Check.\nCrippling nerve toxin?\n\n\n\nCheck. Let's do this thing.", sourceObjectiveStatus = "unverified-source-field" }
quests[14463] = { id = 14463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horses for Duskhaven", description = "Saving the horses might've saved the rest of the town.  They have plenty of carriages in Duskhaven, but not enough horses to pull them.\n\nGo tell Mayor Armstead that the horses you saved are at her disposal.\n\nI'll get things ready and join you in a bit.", sourceObjective = "Speak to Gwen Armstead in Duskhaven.", completion = "Excellent work, {name}.  I think I speak for everyone when I say the sooner we get out of here, the better.", sourceObjectiveStatus = "unverified-source-field" }
quests[14464] = { id = 14464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightning Strike Assassination", description = "The base of the tower is patrolled by the Captain's elite guards. So here's what we're going to do: we're going to grapple straight up to the top, slice-and-dice the VIPs, and bail out using my portable low-altitude parachute. I'll rig the tower to explode behind us. You be sure to grab Captain Grunwald's head for Chawg. Got it?\n\nDo NOT accept this mission unless you are prepared for UNMITIGATED BADASSERY. Is that clear?", sourceObjective = "Talk to Slinky Sharpshiv to ascend the tower and assassinate Captain Grunwald. Collect Captain Grunwald's head.", progress = "I trust you've got good news, {name}?", completion = "I'm impressed by the cleverness of our new goblin allies, but I'm even more impressed by you, {name}. Look at the gaze of terror frozen onto the Captain's face! He never saw your attack coming. Imagine the fear this will cause in Northwatch when they see what happened to one of their precious officers in night elf lands.\n\nWell done, {class}. Our assault proceeds...", sourceObjectiveStatus = "unverified-source-field" }
quests[14465] = { id = 14465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Greymane Manor", description = "It's time for everyone to head to safety.  That includes you, {name}.  Head to Greymane Manor, the others will be there shortly.\n\nDon't worry about me, I'll make sure that everyone makes it out of here in one piece.  Yes, even the few ferals we have in the pens.\n\nOnce you get there, speak to Queen Greymane about the gravity of the situation.", sourceObjective = "Speak to Queen Mia Greymane inside Greymane Manor.", completion = "{name}.  I've heard much about you.\n\nI understand you were crucial in my family's survival during the outbreak in Gilneas City.", sourceObjectiveStatus = "unverified-source-field" }
quests[14466] = { id = 14466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The King's Observatory", description = "You ought to speak to Genn.  He's been locked up in his observatory ever since this ordeal started.\n\nI'm sure he's working on a plan for his people.  He's a very stubborn individual.", sourceObjective = "Speak to King Genn Greymane in the observatory inside Greymane Manor.", completion = "There you are, {name}.  I've been expecting you.\n\nI got word of your recovery and... wait -- do you feel that?", sourceObjectiveStatus = "unverified-source-field" }
quests[14467] = { id = 14467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alas, Gilneas!", sourceObjective = "Look, {name}!  Look at what's become of Duskhaven!\n\nLook at what's become of the last safe place in Gilneas!", sourceObjectiveStatus = "unverified-source-field" }
quests[14468] = { id = 14468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Another Warm Body", description = "Oh have I got a deal for you! Immerse yourself in foreign cultures, go on epic adventures, blow things up, and get paid to do it! Sound too good to be true? Well it's not - this is what we do!\n\nIf you're interested, head over to Gallywix Defense Post on Forlorn Ridge to the north and look for Commander Molotov.", sourceObjective = "Report to Commander Molotov on Forlorn Ridge.", completion = "Latest recruit, eh?\n\nI'll make this short and sweet. We're under contract to keep the naga in the ruins from reaching Gallywix or his property. You handle whatever we ask of you, and I'll see to it that you get paid when all of your rounds are complete.\n\nWelcome to the Bilgewater Battalion.", sourceObjectiveStatus = "unverified-source-field" }
quests[14469] = { id = 14469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hand-me-downs", description = "First things first - we need more supplies for you and the other new recruits. There are some perfectly good standard issue packs on the bodies of our last round of recruits, in the minefield to the north.\n\nTaking their lessons to heart, I'd recommend you avoid stepping on mines yourself.", sourceObjective = "Retrieve 12 Military Supply Packs from the central minefield.", progress = "Nothing wrong with recycled goods.", completion = "You're a light-footed bugger, aren't ya? Good work.\n\nHere are a few of the supplies to keep you lively.", sourceObjectiveStatus = "unverified-source-field" }
quests[14470] = { id = 14470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Military Breakthrough", description = "We've lost contact with Sergeant Dynamo, stationed at the next ridge to the north of the central minefield. They were probably overrun.\n\nHe had our last SFG. Go over there and get it back. Clear out any naga that have broken through while you're there.", sourceObjective = "Kill Warlord Krellen and recover the SFG.", progress = "Where's my rocket launcher, recruit?", completion = "Quick work there, recruit.\n\nShe's a beaut, isn't she? Assembled her myself. I've got special plans for this baby.", sourceObjectiveStatus = "unverified-source-field" }
quests[14471] = { id = 14471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Degree Mortar", description = "Hey bud! Like explosions? Of course you do. Who doesn't like explosions?!\n\nI've got mortars set up on the ridge to the east to hold the naga back. Go forth, recruit. Mortar them... mortar them all! Ahahahah.", sourceObjective = "Use a Goblin Mortar to slaughter 60 Spitelash Attackers", progress = "KABOOM!", completion = "Can you believe they PAY us to do this?", sourceObjectiveStatus = "unverified-source-field" }
quests[14472] = { id = 14472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In The Face!", description = "The naga are using those giants to stamp paths through our minefields. Time to put that SFG to use!\n\nHead over to the entrance to the southern minefield - I think you can figure out the rest.", sourceObjective = "Use an SFG to kill an Enslaved Son of Arkkoroc in the southern minefield.", progress = "Sweet little piece of goblin technology, that thing is.", completion = "BAM! In the face! Nice shot, kid.", sourceObjectiveStatus = "unverified-source-field" }
quests[14473] = { id = 14473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Our Problem Now", description = "Looks like those monkeys will steal anything! Those thieving little monsters have driven the teraptor matriarch into a frenzy by stealing her eggs. Worse yet, the eggs have started to hatch! We've got hungry teraptor hatchlings running around all over the place, looking to make a quick meal out of us!\n\nWe didn't start this, but it's our problem now. You'll have to head into the jungle and kill those hungry teraptor hatchlings before they kill us all.", sourceObjective = "Slay 6 Teraptor Hatchlings.", completion = "Let's just hope we don't have to deal with their mommy later. That would be very bad.", sourceObjectiveStatus = "unverified-source-field" }
quests[14474] = { id = 14474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Escape Pods", description = "{name}, I'm sorry, I thought you were dead!\n\nThis is just crazy. We sailed into a fight between the Alliance and Horde!\n\nYou know, our brothers and sisters still need to be rescued.\n\n<He points out all of the escape pods in the water around you.>\n\nI think I'm going to sit here a while longer and catch my breath. Can you swim around and let them out? Take my pair of thermohydratic flippers so you can get around faster.\n\nLet Sassy know that I'll swim in shortly.", sourceObjective = "Rescue 6 Goblin Survivors.", completion = "Oh, thank heavens that you survived, {name}! I thought for sure that you'd drowned when I saw you go over the side!\n\n\n\nLook at all of these folks you saved!", sourceObjectiveStatus = "unverified-source-field" }
quests[14475] = { id = 14475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grounded!", description = "Do you see a problem with these wind riders, {name}? They're not riding the wind! Every flight I send aloft gets peppered by night elf snipers.\n\nTalrendis sharpshooters are holed up in the southern-most tower, against the mountains. I sent one of these little goblin scrubs to take care of the tower, but I haven't heard a word from him. Go find Bombardier Captain Smooks and beat him with the hurry stick!", sourceObjective = "Find Bombardier Captain Smooks at the southernmost night elf tower at Talrendis Point.", completion = "Reinforcements, at last!", sourceObjectiveStatus = "unverified-source-field" }
quests[14476] = { id = 14476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rigged to Blow", description = "This tower was out of cannon range, so I thought we'd blow it up the old-fashioned way - in person. We set all the main charges but the guards fought us back before we could arm the detonators.\n\n{name}! Get up there and arm the three detonators we placed around the base of the tower. Those things are wired into a pack of thermals I set up along the spine... It'll be some show!", sourceObjective = "Arm the three Explosive Charges located around the base of the southern-most tower at Talrendis Point.", progress = "Did you get 'em? Did you get all three?", completion = "Sweet. Let's torch this banana stand!", sourceObjectiveStatus = "unverified-source-field" }
quests[14477] = { id = 14477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Push the Button!", description = "Lemme check the connections... and we're set. You do the honors, {name}. Push it. Push the button!\n\nPush the button, {name}!\n\nAfter the fireworks, go tell Kroum back at Valormok that his skies are clear.\n\nPush the button!", sourceObjective = "Detonate the explosives!", completion = "Yes, let them burn! Let them burn through the night, so that their flaming tower will light the battlefield beneath us as we rain terror upon their heads.\n\nThank you, {name}. Stay close: the invasion is about to begin...", sourceObjectiveStatus = "unverified-source-field" }
quests[14478] = { id = 14478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation Fishgut", description = "The Bilgewater Battalion are now accepting recruits for OPERATION FISHGUT.\n\nWages will consist of 1 gold piece at the time of operation completion for all active soldiers in good standing. All wages will be forfeited in the event of death. A fee of 20 silver will be charged for any resurrections performed in the line of duty.\n\nAll recruits are to report for duty directly to Commander Molotov under the main cannon.", sourceObjective = "Report for active duty to Commander Molotov under the main cannon in Bilgewater Harbor.", completion = "Welcome back to duty soldier. Good to have you back.", sourceObjectiveStatus = "unverified-source-field" }
quests[14479] = { id = 14479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There Are Many Like It", description = "Enough small talk. Get off your butt and onto a rocket, soldier.\n\nAnd remember, you don't get paid if you're dead.", sourceObjective = "Use a rocket to reach the Shattered Strand, and then report for duty to Lieutenant Drex.", completion = "Bumpy ride?", sourceObjectiveStatus = "unverified-source-field" }
quests[14480] = { id = 14480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extermination", description = "We're sending you in there to clean up this naga infestation. Lethal force has been authorized.\n\nGob Squad will be backing you up on this one, so it should be a cakewalk.", sourceObjective = "Kill 30 Spitelash Naga in the Ruins of Eldarath.", completion = "Your name's getting around... nearly Gob Squad status some would say. You're a vicious one.", sourceObjectiveStatus = "unverified-source-field" }
quests[14482] = { id = 14482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Duty", description = "Citizen!\n\nAs you may have heard, the Horde's attacking just offshore. The fighting's been fierce and relentless.\n\nWe need every able body out there repelling the enemy!\n\nReport to the northernmost dock at once for transport to the battle.\n\nOh, and our official warships are... err, a bit late in their scheduled return. Don't worry though, we've commissioned mercenary vessels to serve in the meantime.\n\nHurry along now, {class}. Stormwind needs you!", sourceObjective = "Ride the mercenary ship to battle.", completion = "Not exactly the battle you had anticipated, I'll wager. But a battle nonetheless, as you shall soon see....", sourceObjectiveStatus = "unverified-source-field" }
quests[14483] = { id = 14483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something is in the Air (and it Ain't Love)", description = "The inside of the card is scribbled with mad, detailed plans to infect most of Azeroth.  You should show this to one of Steamwheedle's investigators immediately!", sourceObjective = "Bring the Faded Lovely Greeting Card to Detective Snap Snagglebolt in Orgrimmar.", progress = "Did you take care of those no-good scheming villains?", completion = "What've you got there?\n\nOh hey, this is big. Real big. Most of the crazy details in one little package. Thanks - you really helped us reel this all in. Good working with ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[14484] = { id = 14484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head of the Snake", description = "They taught us at officers camp to always cut off the head of the snake. Seemed dumb considering we never fought any snakes, but I guess it kind of makes sense now.\n\nTake your men in there and kill Lord Kassarus.", sourceObjective = "Kill Lord Kassarus in the Temple of Zin-Malor.", completion = "Glad you're on our side, soldier.", sourceObjectiveStatus = "unverified-source-field" }
quests[14485] = { id = 14485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ticker Required", description = "Our best demo-man, Ticker, is on assignment with the Gob Squad. He's got WAY more than enough explosives for all the runestones in the ruins.\n\nAll you have to do is get him there and keep him covered - he'll handle the rest.", sourceObjective = "Bring Ticker into the ruins and cover him as he sets up bombs at 3 of the Spitelash Runestones.", completion = "The hope is that that cuts off a major source of their magic. The truth is, we don't really have a clue. Who can pass up an opportunity to blow some stuff up though.", sourceObjectiveStatus = "unverified-source-field" }
quests[14486] = { id = 14486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handling the Goods", description = "Hey there, buddy. Want to make a quick buck?\n\nBring me back any highborne tablets you find in the ruins.", sourceObjective = "Collect 12 Highborne Tablets from the Ruins of Eldarath.", progress = "The blood elves eat those tablets up. Top dollar.", completion = "Excellent. Here's your cut.\n\nGood doing business with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[14487] = { id = 14487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Still Beating Heart", description = "Commander Molotov found a party at the Secret Lab willing to act as buyer for the artifact that you scouted out earlier.\n\nUndoubtedly, it's still in the center of the ruins with the High Priestess, where you initially spotted it. Get it back here undamaged, soldier.", sourceObjective = "Recover the Heart of Arkkoroc from the center of the Ruins of Eldarath.", progress = "I love it when people leave priceless artifacts just lying around.", completion = "Hahah! It's HUGE!\n\nWe'll have you take it back to Uncle Bedlam as soon as everything's cleaned up here and you're ready to go.", sourceObjectiveStatus = "unverified-source-field" }
quests[14488] = { id = 14488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You've Been Served", description = "You made it, huh? Good. I've been waiting for help. No time like the present to act, right?\n\nTake this kit and head deeper inside to serve papers to the leader of that scumbag chemical company, Hummel. The paper's inside. So's a little something to protect you from any chemical tricks they might pull. Use one of the neutralizers when the time comes, all right?", sourceObjective = "Serve the Court Subpoena to Apothecary Hummel in Shadowfang Keep.", progress = "I don't remember ordering a cleaning service... why yes, I am Apothecary Hummel. \n\n...wait, what is the meaning of this? You think these meaningless papers can stop me? Hah!", completion = "What we do here is none of your business...", sourceObjectiveStatus = "unverified-source-field" }
quests[14491] = { id = 14491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Restless Earth", description = "Until recently, a group of dwarves intruded on our lands to the west, carving the earth apart senselessly to search for treasure.  When the very earth itself tore apart, the spirits of the land they had abused rose up and took their revenge.\n\nThe agitated earth spirits still roam the former dig site, {name}.  We must offer them appeasement.\n\nTake this drum with you to the west and play to the spirits.  The rhythm may calm their fury and confusion.", sourceObjective = "Use the Drums of the Soothed Earth to calm 6 Agitated Earth Spirits.", progress = "Is the land satisfied?", completion = "The land is clearly still in great upheaval if it took such effort to calm.\n\nRemember this, {name}.  Do not forget seeing the fate of those who would scar the Earth Mother.", sourceObjectiveStatus = "unverified-source-field" }
quests[20438] = { id = 20438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Suitable Disguise", description = "Getting you inside the Sunreaver's Sanctuary will be tougher than it appears. Only those who possess Sunreaver tabards are permitted entry to sanctuary. If we can get our hands on one, a simple enchantment will do the rest of the work.\n\nOn the balcony above Threads of Fate, you'll find Shandy Glossgleam. I've helped him a few times in the past, so he owes me a favor. He handles laundry for a wide variety of people in the city. Maybe he can find a way to 'lend' you a tabard for a while.", sourceObjective = "Obtain a Borrowed Tabard from Shandy Glossgleam.", progress = "Was Shandy able to help you get a Sunreaver tabard?", completion = "I knew Shandy would find a way to come through for us. Let me get this enchanted and ready for you to use. The sooner you get done with the tabard, the sooner we can get it back to Shandy and the better the chances that its owner will never have missed it.", sourceObjectiveStatus = "unverified-source-field" }
quests[20439] = { id = 20439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Meeting With The Magister", description = "I've placed an enchantment on the tabard that should allow you to slip past the Sunreaver Sanctuary's defenses for a short period of time. You should have enough time to find your way into The Filthy Animal and meet up with the Sunreaver contact there, one Magister Hathorel.\n\nObtain the copy of Ancient Dragonforged Blades that his men borrowed from Wyrmrest while your disguise holds, and return it to me.", sourceObjective = "Retrieve the Ancient Dragonforged Blades tome from Magister Hathorel.", progress = "Have you recovered that book?", completion = "Excellent work. Now that this is in our hands, we must get it to Caladis Brightspear as soon as possible. We can't risk the book falling back into Sunreaver hands.\n\nI'll ensure that Shandy Glossgleam gets his tabard back without incident, along with a healthy reward for his help.", sourceObjectiveStatus = "unverified-source-field" }
quests[20440] = { id = 20440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poison Water", description = "Our sacred wells have been tainted, and I will need your help to fix this.\n\nTo cleanse each well, I must create a cleansing totem, then you must bring the totem to the well and perform a cleansing ritual.\n\nFirst we will create a cleansing totem for the Winterhoof Water Well.  To do this, the land must offer its aid. Hunt prairie wolves for their paws and adult plainstriders for their talons.  They are to the southwest.\n\nReturn to me with the paws and talons, {name}.", sourceObjective = "Collect 6 Prairie Wolf Paws and 4 Plainstrider Talons.", progress = "Do you have the paws and talons, {name}?", completion = "You have done well, {name}.  I will take these and bind their power into a totem of cleansing.", sourceObjectiveStatus = "unverified-source-field" }
quests[20441] = { id = 20441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rite of Vision", description = "Again, be sure you are ready to leave Bloodhoof Village behind, {name}. The next step on your journey will take you far from here.\n\nYour path continues to lead onward, across the fields of Mulgore, the eyes of the Earth Mother on you at all times. When you are ready, consume the waters near the tribal fire. Once you have ingested the holy waters, your eyes will be opened, and the spirits will guide you.", sourceObjective = "Consume the Water of Vision in front of the tribal fire in Bloodhoof Village.", completion = "Be not afraid, {name}. You have successfully passed the Rite of Vision.", sourceObjectiveStatus = "unverified-source-field" }
quests[23733] = { id = 23733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rites of the Earthmother", description = "Today, you have undertaken a rite of passage far more difficult than we ask of most of our youths. Be proud. Now, it is time for you to continue on your journey.\n\nTo the west, beyond our burial ground, you will find a path winding up the mesa. Follow it to the top, and speak with Dyami Windsoar.\n\nWalk with the Earth Mother, friend. You will always be welcome here.", sourceObjective = "Speak to Dyami Windsoar atop Fargaze Mesa.", completion = "If you are prepared to leave Camp Narache behind, I will help call the spirits to guide you onwards.", sourceObjectiveStatus = "unverified-source-field" }
quests[24215] = { id = 24215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rite of the Winds", description = "Look, {name}. The rolling plains of Mulgore stretch before you: our home, the cradle of the Earth Mother. Here she provides us with all we could ever need, a peaceful and verdant land. This is what you will fight to protect.\n\nYour journey will take you far beyond her sheltering arms, to the farthest and cruelest regions of this world, and beyond.\n\nBelow us is Bloodhoof Village. The first step on your true path begins now. Drink deep of the Water of Vision, and let the spirits guide you onward.", sourceObjective = "Drink the Water of Vision.\n\nProvided item:", completion = "Welcome to Bloodhoof Village, hero.  I am glad the spirits have guided you safely here.", sourceObjectiveStatus = "unverified-source-field" }
quests[24216] = { id = 24216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Alliance is an insidious enemy, {name}.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens.\n\nToday we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!", sourceObjective = "Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", completion = "The Horde is in your debt, {name}.  You've made your people proud with your courage in defending our lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[24217] = { id = 24217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Alliance is an insidious enemy, {name}.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens.\n\nToday we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!", sourceObjective = "Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", completion = "The Horde is in your debt, {name}.  You've made your people proud with your courage in defending our lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[24218] = { id = 24218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory.\n\nTheir need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!", sourceObjective = "Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", completion = "Excellent work, {name}.  The integrity of our borders must be preserved at all costs!", sourceObjectiveStatus = "unverified-source-field" }
quests[24219] = { id = 24219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory.\n\nTheir need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!", sourceObjective = "Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "What news do you bring from the front, {name}?", completion = "Excellent work, {name}.  The integrity of our borders must be preserved at all costs!", sourceObjectiveStatus = "unverified-source-field" }
quests[24220] = { id = 24220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle of Arathi Basin that demands immediate reinforcements.\n\nReturn to me with news of victory, {name}.  We cannot allow the Horde scum to secure the resources that are rightfully ours!", sourceObjective = "Win an Arathi Basin battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", completion = "Excellent news, {class}!  If our tactical deployments continue to be this successful, the Horde will be in full retreat before long.", sourceObjectiveStatus = "unverified-source-field" }
quests[24221] = { id = 24221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "Arathi Basin is on the verge of being lost to Alliance forces.  We must send reinforcements at this very moment or all our efforts will have been in vain.\n\nDo not delay, {class}, go to Arathi Basin and crush the enemy.  Victory to the Horde!", sourceObjective = "Win an Arathi Basin battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", completion = "You've brought great honor to the Horde, {name}.  Your victory today will ensure a thousand victories tomorrow!", sourceObjectiveStatus = "unverified-source-field" }
quests[24223] = { id = 24223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle of Arathi Basin that demands immediate reinforcements.\n\nReturn to me with news of victory, {name}.  We cannot allow the Horde scum to secure the resources that are rightfully ours!", sourceObjective = "Win an Arathi Basin battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", completion = "Excellent news, {class}!  If our tactical deployments continue to be this successful, the Horde will be in full retreat before long.", sourceObjectiveStatus = "unverified-source-field" }
quests[24224] = { id = 24224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory.\n\nTheir need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!", sourceObjective = "Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", completion = "Excellent work, {name}.  The integrity of our borders must be preserved at all costs!", sourceObjectiveStatus = "unverified-source-field" }
quests[24225] = { id = 24225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Alliance is an insidious enemy, {name}.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens.\n\nToday we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!", sourceObjective = "Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", completion = "The Horde is in your debt, {name}.  You've made your people proud with your courage in defending our lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[24226] = { id = 24226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "Arathi Basin is on the verge of being lost to Alliance forces.  We must send reinforcements at this very moment or all our efforts will have been in vain.\n\nDo not delay, {class}, go to Arathi Basin and crush the enemy.  Victory to the Horde!", sourceObjective = "Win an Arathi Basin battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24426] = { id = 24426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley", description = "We've recently come extremely close to driving the Stormpike invaders from Alterac Valley.  As a result we're redirecting all our reinforcements to aid the Frostwolf Clan.\n\nA decisive victory there would free up the resources we need to crush the Alliance scum on all the other battlefronts.\n\nGo, {name}.  Earn great honor by heeding the call of the brave Frostwolf warriors.", sourceObjective = "Win an Alterac Valley battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran or Shattrath.", completion = "There is no greater honor than driving invaders from Horde territories.  We salute your great courage in aiding our forces today!", sourceObjectiveStatus = "unverified-source-field" }
quests[24427] = { id = 24427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle for Alterac Valley that's in most need of brave combatants.\n\nGo now, {name}, and aid the Stormpike Expedition.  We cannot allow the Frostwolf Clan to get away with the violence they've inflicted on our brethren!", sourceObjective = "Win an Alterac Valley battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran or Shattrath.", completion = "Just what I wanted to hear!  A victory in Alterac Valley - even a temporary one - is crucial to our overall strategy against the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[24428] = { id = 24428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Most Puzzling Circumstance", description = "You have accomplished the truly impossible. The brood mother of the Black Dragonflight lies dead at your feet. Seize her head and deliver it to Zardeth of the Black Claw.", sourceObjective = "Take the Head of Onyxia to Zardeth of the Black Claw in the basement of the Slaughtered Lamb.", progress = "By Nozdormu's teeth!", completion = "What? How did you get this? Isn't she... Never mind the details, I suppose. You'll be wanting one of these baubles as recompense, no doubt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24429] = { id = 24429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Most Puzzling Circumstance", description = "You have accomplished the truly impossible. The brood mother of the Black Dragonflight lies dead at your feet. Seize her head and deliver it to Neeru Fireblade.", sourceObjective = "Take the Head of Onyxia to Neeru Fireblade in the Cleft of Shadow.", progress = "What is the meaning of this?!", completion = "You've brought me the head of someone who is... No, best not to think about it too hard. You'll be wanting recompense for your heroic deeds, no doubt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24430] = { id = 24430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blacken the Skies", description = "{name}! Give us a hand here, will ya? Gorsch here had a bad experience at the all-you-can-eat seafood joint back in town, and now we're short a pilot.\n\nMy job was to take out those elven glaive throwers before they cut our air units to ribbons. Hop on this wind rider and take to the skies! One of my bombardier buddies will ride with you and bomb the targets at your command.\n\nAnd hey! Chuck a bomb straight at the night elven command center - the large building south of here, beside the bridge. Glorious!", sourceObjective = "Mount a Grounded Wind Rider and fly over Talrendis Point. Destroy 6 Talrendis Glaive Throwers and bomb the Command Center.", progress = "More bombs. More bombs!", completion = "Oh yeah! I love the smell of freshly-cratered dirt!\n\nWord around camp is that the elven front line is collapsing back toward the river. Talk to Chawg and see if there's anything you can do to help seal the deal.", sourceObjectiveStatus = "unverified-source-field" }
quests[24431] = { id = 24431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waterlogged Recipe", description = "This appears to be the remains of a mixture for potent wine.  Perhaps the proprietor of One More Glass in Dalaran would be interested in it....", sourceObjective = "Bring the Waterlogged Recipe to Christi Stockton in the Dalaran city.", progress = "Wine is only as fine as the person drinking it, I always say.", completion = "This is quite a find, {name}.  I can't have you selling this to anyone else, so I'm willing to offer generously.", sourceObjectiveStatus = "unverified-source-field" }
quests[24432] = { id = 24432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sea Legs", description = "Welcome to The Briny Cutter, {class}.\n\nI am Erunak, the last surviving passenger of this once-proud vessel.\n\nI'm afraid your travails have only just begun. The naga have been attacking here relentlessly.\n\nYou're not equipped to be of much help down here yet, but I can remedy that.\n\nJust outside this ship live a special breed of starfish. Bring me some of them along with a conch shell. I'll prepare an enchantment that should help to increase your chances of survival.", sourceObjective = "Erunak in The Briny Cutter wants you to bring him 3 Saltwater Starfish and a Conch Shell from Seafarer's Tomb.", progress = "It is good to see that you're still alive, {race}.\n\nHave you found the items I require?", completion = "Here you are, {class}. With this you should find maneuvering in the sea to be nearly effortless. \n\nNow we must get to work. There is much to be done in little time.", sourceObjectiveStatus = "unverified-source-field" }
quests[24433] = { id = 24433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let Them Feast on Fear", description = "Our grunts are strong but have no initiative. They're fighting toe-to-toe on the front lines. But an independent {class} like yourself - well, someone like you can slip behind the lines and cause some real havoc deep within the enemy redoubt.\n\nCut a swath of destruction through the heart of Talrendis, {name}! Slay our foes in territory they think is secure, leaving blood and fear in your wake.", sourceObjective = "Fight your way across Talrendis Point, slaying 12 Talrendis Defenders and 6 Talrendis Sentinels.", completion = "Lok'tar ogar, {name}! As they discover the bodies of their comrades they will learn that no place is safe from the fury of the horde, and their will to fight will crumble.", sourceObjectiveStatus = "unverified-source-field" }
quests[24434] = { id = 24434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Commando Drop", description = "Are you sensitive to the tremors of the local ley-lines, {name}? I can feel the occasional thrum, like the plucking of a string. It's the kind of resonance I'd expect from a long-range summoning spell. The Lorekeepers in Talrendis, with their laughably primitive magics, are trying to summon in backup from Darnassus.\n\nWe can use this to our advantage, {name}. If you can compromise their summoning stone, we can teleport a crack team of commandos behind enemy lines.\n\nLocate the summoning stone in Talrendis!", sourceObjective = "Slay 5 Talrendis Lorekeepers and locate a Lorekeeper Summoning Stone somewhere within Talrendis Point.", completion = "Images of a great and distant tree flood your mind. Your stomach lurches as you reorient the stone, briefly filling your senses with visions of a fiery portal, a towering mountain, a frigid wasteland, and a terrible scar across the earth.\n\nAfter a moment, the magical energies of the stone calm, and you feel you are but a step away from Valormok. Andorel's invasion can begin...", sourceObjectiveStatus = "unverified-source-field" }
quests[24435] = { id = 24435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mop Up", description = "There are a lot of naga left on this beach. Looks like you have some wet work ahead of you, <son/girl>.", sourceObjective = "Kill 12 Spitelash Naga on the Shattered Strand.", progress = "After this, I think I may need to move away from the ocean. The smell of fish is almost too much to stand.", completion = "Good clean fun.", sourceObjectiveStatus = "unverified-source-field" }
quests[24436] = { id = 24436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halo Drops", description = "We've got \"soldiers\" all over the beach trying to get out of their work by dying on us. Find the slackers and use this flaregun to call in a priest to take care of the situation.\n\nWe can't have men thinking they can get off that easy.", sourceObjective = "Call in Airborne Priests at the bodies of 8 Wounded Soldiers on the Shattered Strand.", completion = "Fine job there, bud. We'll have this beach cleaned up in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[24437] = { id = 24437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Come, First Served", description = "There's some gorgeous beach front property along the shore. I can market this stuff for 10 times what construction will cost me.\n\nThe prime spots are that naga pagoda to the south, the tower right next to the water, and the ruins at the far northern end of the beach. I'll give you some coin if you claim them for me before the fighting clears out.", sourceObjective = "Plant Ruckus' Territorial Claim Flag next to the prime real estate locations along the Shattered Strand.", completion = "Hah hah! Brilliant. Right fine job there, boy.", sourceObjectiveStatus = "unverified-source-field" }
quests[24438] = { id = 24438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exodus", description = "We have no choice, {name}.  We must move further inland.\n\nI don't like it one bit, but we're vulnerable here.\n\nReturn to the stables below the manor.  Let's get everybody on carriages and send them eastbound.  I pray it's not too late.", sourceObjective = "Board a carriage below Greymane Manor.", completion = "Thanks for stopping, {name}.  Our carriage got hit pretty bad.\n\nThe one in front of us got it worse.", sourceObjectiveStatus = "unverified-source-field" }
quests[24439] = { id = 24439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conquest of Azshara", description = "{name}! Was it you who piloted the wind rider who bombed the command center? It was a direct hit!\n\nMy scouts tell me that you gravely wounded Jarrodenus, flight master of the night-elven skychasers and de facto commander of the opposition.\n\nThe opportunity to strike is now - I don't have time to assemble a full assault. Rush the command center building and kill Commander Jarrodenus before his backup arrives. Bring me his head... and Azshara is ours!", sourceObjective = "Slay Commander Jarrodenus in Talrendis Point and collect his head.", progress = "Is Jarrodenus still barking orders, or have you removed from him the burden of his head?", completion = "...Then it is done!\n\n<Chawg surveys the battlefield.>\n\nThere are still pockets of resistance around our camp, but this rearguard action appears to be masking a full-fledged retreat to Ashenvale. Azshara is ours!\n\nThe Warchief will hear of this victory and your part in it. But we will surely need the help of a {class} like you elsewhere. Be sure to speak with Kroum here in camp before you leave.", sourceObjectiveStatus = "unverified-source-field" }
quests[24440] = { id = 24440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterhoof Cleansing", description = "I have crafted the totem to cleanse the Winterhoof Water Well.  Now, you must take it to the well and perform a cleansing ritual.  The well is to the southeast, but be warned: whoever did this may still be there, laying in wait.\n\nThis may prove very dangerous, {name}.  Be careful...but do not let the defilers of our well escape.", sourceObjective = "Use the Winterhoof Cleansing Totem at the Winterhoof Water Well.", progress = "Do not delay, {name}.  The Winterhoof Well must be purified!", completion = "The Grimtotem...\n\n<Mull scowls.>\n\nI'd hoped to see the end of my days before {race} attacked other {race} senselessly on the very plains of Mulgore.  But be proud, {name}.  You have done a great thing for the land, and for our people.", sourceObjectiveStatus = "unverified-source-field" }
quests[24441] = { id = 24441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderhorn Totem", description = "There is more work to be done.  We must create a new totem to cleanse the Thunderhorn Well.\n\nYou must gather the claws of the predators of the Mulgore plains.  Hunt prairie stalkers for their stalker claws and flatland cougars for their cougar claws, then return to me.\n\nYou will find the prairie stalkers and flatland cougars to the east and west.", sourceObjective = "Collect 6 Stalker Claws and 6 Cougar Claws.", progress = "{name}, do you have the claws I sent you to gather?  The Thunderhorn Water Well grows more tainted with each passing hour!", completion = "Thank you, {name}.  The purity with which these beasts hunt is vital in the creation of the next cleansing totem.\n\nThe Thunderhorn Well is a symbol of my own tribe, and to know it is being desecrated by our own kind raises a fury in me I haven't felt for years.", sourceObjectiveStatus = "unverified-source-field" }
quests[24442] = { id = 24442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Plans Of The Kvaldir", description = "Looking over the captured attack plans, you find a map of the Eastern Kingdoms and Kalimdor with major settlements marked. Reading over the orders, you learn that  Kvaldir captains have drafted plans for a series of devastating raids.\n\nAccording to the orders, the attacks are to begin after Mistcaller Yngvar \"consults the Heart of the Mists.\" Perhaps you could delay the attacks by capturing the omen from the Mistcaller's Cave on the western side of Hrothgar's Landing and notify Justicar Mariel Trueheart.", sourceObjective = "Recover the Heart of the Mists and bring it and the Kvaldir Attack Plans to Justicar Mariel Trueheart at the Argent Tournament Grounds.", progress = "What is it that you've found, {name}?", completion = "<Mariel accepts the orders and the captured seeing crystal and examines both.>\n\nGood work, {name}, and quick thinking. I'm sure the theft of this trinket won't slow them down for long, but I think you've bought us time to warn the leaders of the Horde and Alliance about the impending attacks.", sourceObjectiveStatus = "unverified-source-field" }
quests[24443] = { id = 24443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captured Hunter", description = "The quilboar have not only razed our buildings, but have taken tauren captives. I saw them take Honu Staghunter, a young hunter trainer of ours, away in one of their foul cages.  Please, find a key on one of the quilboar's bodies and go save her!", sourceObjective = "Obtain a Crude Key from one of the Bristleback Quilboar, and use it to unlock the Quilboar Cage holding Honu Staghunter.", sourceObjectiveStatus = "unverified-source-field" }
quests[24444] = { id = 24444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captured Shaman", description = "The quilboar have not only razed our buildings, but have taken tauren captives. I saw them take Miira Thunderhoof, a young shaman trainer of ours, away in one of their foul cages.  Please, find a key on one of the quilboar's bodies and go save her!", sourceObjective = "Obtain a Crude Key from one of the Bristleback Quilboar, and use it to unlock the Quilboar Cage holding Miira Thunderhoof.", sourceObjectiveStatus = "unverified-source-field" }
quests[24445] = { id = 24445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captured Druid", description = "It's fallen to some of our youngest to defend our camp, {name}, and many of our bravest apprentices are out there as we speak, fighting the quilboar.  I fear for their safety...\n\nPlease, look for the young druid Keshu Treehoof to the east, deep within quilboar territory. If you find her and the other apprentices alive, they may be able to help you.", sourceObjective = "Find Keshu Treehoof.", sourceObjectiveStatus = "unverified-source-field" }
quests[24446] = { id = 24446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captured Sunwalker", description = "The quilboar have not only razed our buildings, but have taken tauren captives. I saw them take Bowe Dawnhorn, a young Sunwalker, away in one of their foul cages. Please, find a key on one of the quilboar's bodies and go save him!", sourceObjective = "Obtain a Crude Key from one of the Bristleback Quilboar, and use it to unlock the Quilboar Cage holding Bowe Dawnhorn.", sourceObjectiveStatus = "unverified-source-field" }
quests[24448] = { id = 24448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Promotion", description = "Commander Molotov sent word directly that you should be dispatched to our forward post. We're preparing to send squads into the ruins to rout the naga and recover the artifact, and he would like you to lead one of them.\n\nGet to the northwest corner of the beach and follow the path up to our forward post.", sourceObjective = "Report to Captain Tork at the forward post in the Ruins of Eldarath.", completion = "{name}! You made it in one piece, good.\n\nWe've got a lot of work for you to handle for us inside the ruins, but we're sending you in with the best to take care of it. You're working with GAMA Force now, Goblin Army: Mergers and Acquisitions. Molotov says you can handle it - that's all I need to hear.", sourceObjectiveStatus = "unverified-source-field" }
quests[24449] = { id = 24449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shore Leave", description = "We're looking pretty good here at this point. It's definitely been a pleasure working with you, soldier.\n\nIf you're ready to take the artifact back, we've got a Gyrocopter ready to take you back to Bilgewater Harbor so that you can deliver it to Uncle Bedlam personally.", sourceObjective = "Bring the Heart of Arkkoroc to Uncle Bedlam in Bilgewater Harbor.", progress = "Ah, the man of the hour!", completion = "And you come with the artifact! The operation was a success then. Mergers and Acquisitions can definitely handle themselves. This thing will fetch quite a pretty penny.\n\nAnd you - I heard you did some impressive work down there. You may well have cut-down expenses by 10% single-handedly. That's the kind of smarty businessman I want in my army!\n\nHere are your wages, as promised. And a little something extra too - I hope you like it.", sourceObjectiveStatus = "unverified-source-field" }
quests[24451] = { id = 24451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Audience With The Arcanist", description = "I've placed an enchantment on the tabard that should allow you to slip past the Silver Enclave's defenses for a short period of time. You should have enough time to find your way up to the top level of the Silver Enclave and meet up with the Silver Covenant's man there, known as Arcanist Tybalin.\n\nWhile disguised, obtain the copy of Ancient Dragonforged Blades that his men borrowed from Wyrmrest, and return the book to me.", sourceObjective = "Retrieve the Ancient Dragonforged Blades tome from Arcanist Tybalin.", progress = "Did you recover the book from Wyrmrest?", completion = "Excellent work. Now that this is in our hands, we must get it to Myralion Sunblaze as soon as possible. We can't risk the Silver Covenant taking the book from us again.\n\nI'll get that tabard back to Shandy and see that he's well compensated for his assistance. Once the book is in Myralion's hands, the Silver Covenant won't be a threat anymore.", sourceObjectiveStatus = "unverified-source-field" }
quests[24452] = { id = 24452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Profitability Scouting", description = "Things seem to be quieting down a bit. Gallywix will probably keep forking out cash to keep us posted here, but I have a feeling we might be able to milk a bit more out of the deal.\n\nNaga and Sea Giants aren't normally friends, so the naga must be controlling them somehow. Take this stealth field generator, get in those ruins, and let me know if you find something that looks really pricey.", sourceObjective = "Use the stealth field generator to infiltrate the Ruins of Eldarath and identify the Heart of Arkkoroc.", progress = "Our stealth field generator has the same acronym as our rocket launcher. Probably poor planning on our part.", completion = "Hahah! Sweet deal. I'll get the ball rolling on this. All I need now is to find a buyer and get the go-ahead from Uncle Bedlam.\n\nHere are your wages for your work here. Excellent work, soldier.", sourceObjectiveStatus = "unverified-source-field" }
quests[24453] = { id = 24453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Private Chat", description = "Look... one last favor before you run off.\n\nPrivate Worcester is still back at that tower \"recruiting.\" Go and let him know that we're good to pack it up now. Back to town.\n\nPleasure working with you, recruit.", sourceObjective = "Speak to Private Worcester at the Orgrimmar Rocketway Exchange.", completion = "What?! I got left out of the action completely? Are you serious?\n\nAlright, alright... no shooting the messenger. Thanks for the news, bud. Maybe I'll see you back at town.", sourceObjectiveStatus = "unverified-source-field" }
quests[24454] = { id = 24454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return To Caladis Brightspear", description = "We must get this book to Caladis Brightspear immediately. Would you bring it to him? I cannot rely on anyone else to transport the book and you have proven adept at keeping the Sunreavers at bay.\n\nTake it with you to Quel'Delar's rest, south of the Argent Tournament Grounds in Icecrown. Caladis and the sword will be waiting. The sooner we can identify the blade, the sooner we can claim it.", sourceObjective = "Bring Ancient Dragonforged Blades to Caladis Brightspear at Quel'Delar's Rest.", progress = "We've been expecting your return. What has kept you?", completion = "<Caladis accepts the heavy book and begins leafing through it.>\n\nI knew the symbols on the blade were familiar. The weapon was most certainly forged by the dragons and gifted to one of the mortal races, but which blade is this, and how did it come to rest in Icecrown?", sourceObjectiveStatus = "unverified-source-field" }
quests[24455] = { id = 24455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rapid Deployment", description = "You will be reporting for active duty immediately. Captain Desoto is overseeing deployment just down the ramp at the rocket launch station.\n\nMake us rich, soldier. Dismissed!", sourceObjective = "Report to Captain Desoto in Bilgewater Harbor for deployment.", completion = "Nice to meet you soldier. Commander Molotov speaks highly of you.", sourceObjectiveStatus = "unverified-source-field" }
quests[24456] = { id = 24456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderhorn Cleansing", description = "The Grimtotem are a tribe that believe all of Kalimdor should belong to the tauren alone. Their hate and anger led to a corrupting thirst for power. Magatha, their leader, poisoned our High Chieftain, Cairne Bloodhoof, and attempted to take Thunder Bluff for herself; she was defeated, and the Grimtotem exiled.\n\nNow they seek to ruin Mulgore itself as they are driven out. Quickly, {name}, you must go to the Thunderhorn Water Well in the north and perform the ritual!", sourceObjective = "Use the Thunderhorn Cleansing Totem at the Thunderhorn Water Well.", completion = "You've done great honor for both me and my ancestors today.  Please, take this with my gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[24457] = { id = 24457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rite of Vision", description = "I cannot thank you enough for cleansing my tribe's well, {name}, and for fighting the savage Grimtotem to do it. But there is more to be done, and it is time for your journey to lead you beyond Bloodhoof Village.\n\nZarlman Two-Moons stands by the fire in the north end of the village.  Go speak with him and learn of the next ritual you must undertake.", sourceObjective = "Speak with Zarlman Two-Moons in Bloodhoof Village.", completion = "I sensed you would be coming to me, {class}. I can always recognize one who is trying to pass the Rites of the Earthmother.", sourceObjectiveStatus = "unverified-source-field" }
quests[24458] = { id = 24458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hello to Arms", description = "{name}, I've taken the purified sample of Azsharite you rescued from the lab and I've weaponized it. If my calculations are correct, it will detonate with enough force to level a city.\n\nIf I'm wrong, we may cleave the planet in two.\n\nThe only way to find out is a test-firing! Deliver the Azsharite core to the giant cannon in Bilgewater and report to Bleenik Fizzlefuse. My pilot-for-hire Friz Groundspin here can give you a ride.\n\nI'll follow... from a safe distance.", sourceObjective = "Deliver the Armed Azsharite Core to Bleenik Fizzlefuse at Bilgewater Harbor. Speak with Friz Groundspin for a free airlift.", progress = "What's that you've got there - did Grapplehammer send you?", completion = "Oh! This is it! It's the big one!\n\n<Fizzlefuse calls out to his workers.>\n\nWe're in business boys!", sourceObjectiveStatus = "unverified-source-field" }
quests[24459] = { id = 24459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morin Cloudstalker", description = "You may have heard of the Venture Company. They are a goblin \"cartel\", something like a tribe.\n\nWhile one of these cartels has joined us in the Horde, the Venture Company is loyal only to greed. These greedy goblins and their workers have tried to exploit the resources of Mulgore before, to little success.\n\nOne of our outrunners, Morin Cloudstalker, has gone to check the remains of one of the goblin caravans. If you wish to help him, follow the road out of the village to the east.", sourceObjective = "Find Morin Cloudstalker to the east of Bloodhoof Village.", completion = "Well met. If Ahmo has already explained the minor quibbles of what kind of goblin we'll be driving from our lands, let's get to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[24460] = { id = 24460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Order", description = "Hey there {class}, I need you to solve the Cataclysm. Go hunt me some zombies.", sourceObjective = "Paul's Test Questgiver wants you to kill zombies.", sourceObjectiveStatus = "unverified-source-field" }
quests[24461] = { id = 24461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reforging The Sword", description = "We cannot allow Quel'Delar to remain broken and disgraced. Take the remnants of the sword, along with the battered hilt you discovered, and venture into the Pit of Saron within Icecrown Citadel.\n\nIn the pit, the Lich King uses slaves to mine, process, and transform saronite ore. This infused saronite is what we will use to rebuild Quel'Delar.\n\nYou must gather bars of infused saronite and capture the forgemaster's hammer, then bring them to the forgemaster's anvil and reforge the sword.", sourceObjective = "Obtain 5 Infused Saronite Bars and the Forgemaster's Hammer and use them to make the Reforged Quel'Delar.", progress = "Were you able to reconstruct Quel'Delar?", completion = "You have remade the blade of Quel'Delar, although Blood-Queen Lana'thel proclaimed we could not! The blade must still be tempered, but she and her master will not stand in our way!", sourceObjectiveStatus = "unverified-source-field" }
quests[24463] = { id = 24463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probing into Ashenvale", description = "Even as the Darnassian scum pull back from Azshara, I've been getting mixed reports from my riders stationed in Ashenvale, to the west. The night elves may be making an assault on our territory in the Barrens.\n\n{class}, I need you to slip across the border and speak to one of my scouts. Look for Kulg Gorespatter just across the bridge at the southwest edge of Talrendis Point. Find out what's happening in those woods!", sourceObjective = "Speak with Kulg Gorespatter in Ashenvale.", completion = "You say Talrendis Point has fallen? That's good news!\n\nIt also explains the exodus of elves I've seen along this road.", sourceObjectiveStatus = "unverified-source-field" }
quests[24467] = { id = 24467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fade to Black", description = "Now we put an end to all this madness. We need to rout the black dragonflight from Azshara entirely before they can return with any communication for their master.\n\nI still don't know what they have up their sleeve for capturing us, so I'd like to ask this one last thing of you - go into sable ridge and kill their leaders, Twilight Lord Katrana and Malicion.\n\nIf things get hairy, I will come help. I just don't want to risk falling into whatever trap they set for Azuregos.", sourceObjective = "Kill Twilight Lord Katrana and Malicion in Sable Ridge.", progress = "I will be glad to be done with these wretches.", completion = "You truly amaze me, mortal. It's rare to meet someone so dedicated and resourceful.\n\nAzuregos and I are likely to depart Azshara and remain discrete for a while. I do hope that we meet again someday though. Perhaps to put an end to Deathwing himself.\n\nFarewell, {name}. Stay safe.", sourceObjectiveStatus = "unverified-source-field" }
quests[24468] = { id = 24468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranded at the Marsh", description = "The ogres got two of our stagecoaches: this one and one that fell into the marsh just north of here.\n\nI want you to head there and rescue any survivors while we hatch up a plan to deal with these ogres.", sourceObjective = "Rescue 5 Crash Survivors at the Hailwood Marsh.", progress = "Were any of the passengers still alive?", completion = "You've done it again, {name}.  You have my thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[24469] = { id = 24469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hold the Line!", description = "Hey, you there!  Ye're a stout-looking {class}.  Lend us a hand?\n\nIt looks like today's big earthquake shook a bunch o' those barbarous troggs out of the ground, and they're sure steamed about something.  My men are doing what they can to hold them off, but we could use a hand.\n\nDo yer part - head just south of here and help dig me mountaineers outta trouble.  We've got to hold the line!", sourceObjective = "Slay 6 Rockjaw Invaders.", progress = "How many of 'em did ya get?", completion = "Impressive work, laddie.  We can hold the perimeter from here on out.\n\nHere, take this for yer troubles.  It might come in handy, as I've got something more important to ask of ye...", sourceObjectiveStatus = "unverified-source-field" }
quests[24470] = { id = 24470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Give 'em What-For", description = "Alright, {name}, listen up.  I know a thing or two about troggs, and one of those things is that the biggest, strongest troggs get the most respect.  The brutes value strength over anything else.\n\nYe see those great big troggs sitting back behind the front lines?  They're the closest they have to what ye'd call a leader.  Go take out a few, and show 'em what it means to mess with the Sons of Ironforge!", sourceObjective = "Kill 3 Rockjaw Goons.", completion = "Hmm... they blame us for destroying their home, ye say?  Well, that wasn't us, that was the horrible earthquake we had earlier today.  Are they that dense that they can't see we nearly lost our camp too?\n\nCan't blame a trogg for fightin' for his home, though.", sourceObjectiveStatus = "unverified-source-field" }
quests[24471] = { id = 24471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid for the Wounded", description = "{name}, listen!  Unlike Joren, I've no need for yer blade, but I do need someone with a steady hand and a bit o' courage.\n\nOur mountaineers are trained to protect the village from the odd wolf attack... not an all-out trogg invasion!  Many of our best have succumbed to wounds and exhaustion, and I need yer help bandaging them up.\n\nHere, take my first aid kit and assist as many as ye can.", sourceObjective = "Use Sten's First Aid Kit on 4 Wounded Coldridge Mountaineers.", completion = "Many of those that y'saved have already made it back to camp.  The wounds're well-dressed!  Ye might have a future in first aid, if ye're into that sorta thing.", sourceObjectiveStatus = "unverified-source-field" }
quests[24472] = { id = 24472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Introductions Are in Order", description = "The Forsaken are right on our heels and now these ogres are trying to flank us, {name}.\n\nThey're servants of the ettin Koroth -- the meanest, most destructive force in all of Gilneas.\n\nIf we can bait Koroth into charging the Forsaken's forward force, we should be able to cover our retreat and buy some time.\n\nThe only way this can work is if we make Koroth furious.  It won't be enough to just kill his minions.  We need to swipe his most prized possession, a tiger-skinned banner.", sourceObjective = "Kill 4 Ogre Minions and obtain Koroth's Banner in Koroth's Den.", progress = "How did it go, {name}?", completion = "You definitely got the ettin angry, {name}.   I heard him myself.\n\nLet's hope this works.", sourceObjectiveStatus = "unverified-source-field" }
quests[24473] = { id = 24473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lockdown in Anvilmar", description = "We appreciate yer help out here, but there may be a place where they need ye even more.\n\nDue to the trogg attacks - not to mention that massive earthquake we just had - we're putting all civilians on lockdown inside Anvilmar, just up the hill to the northwest.\n\nGo an' talk to me wife, Jona, inside Anvilmar.  I'm certain she's in need of an able-bodied <man/lass> such as yerself.", sourceObjective = "Speak with Jona Ironstock in Anvilmar.", completion = "Achh.. and what do YOU want?  Can't ye see I'm busy in here!  Go an' bother someone else, I haven't the time.\n\nWait, what's that ye say?  Joren sent you to help?  Well why didn't ye say so?", sourceObjectiveStatus = "unverified-source-field" }
quests[24474] = { id = 24474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Things First: We're Gonna Need Some Beer", description = "I don't know how ANYONE expects to get any work done around here if we don't have any ale!  Our beer level here in Anvilmar is dangerously low.\n\nLucky for us, we've stowed some backup kegs for just such an occasion.  West of Anvilmar, along the valley's northern border, ye'll find kegs of Stormhammer Stout and Theramore Pale Ale.  Just to the east of here, ye'll find a stash of Gnomenbrau.  That's me personal favorite.", sourceObjective = "Obtain a Cask of Stormhammer Stout, a Cask of Theramore Pale Ale, and a Cask of Gnomenbrau.", progress = "The ale, darling, the ale!", completion = "<Jona drinks deeply from the Gnomenbrau.>\n\nAhh... that hits the spot.  Now we can get some work done around here.", sourceObjectiveStatus = "unverified-source-field" }
quests[24475] = { id = 24475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All the Other Stuff", description = "If we're going to be on lockdown for any extended period o' time, we're gonna need some food, and some blankets to keep the wee ones warm.  Would ye mind headin' outside and gatherin' up some supplies?\n\nYe'll find that a few o' the small boars actually have some healthy-sized haunches... good for eatin'.  We'll also need some pelts from the young wolves.\n\nYe'll find animals almost anywhere ye go in Coldridge.", sourceObjective = "Obtain 3 Boar Haunches and 4 Ragged Wolf Hides.", progress = "The people are gettin' restless.  D'ye have the supplies yet?", completion = "This'll have to do for now.  We've a lot of people to feed here, but we've got to make do with what we've got.  With any luck, King Bronzebeard in Ironforge will send us some help shortly.", sourceObjectiveStatus = "unverified-source-field" }
quests[24476] = { id = 24476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempering The Blade", description = "At last, the pieces of Quel'Delar are rejoined and the blade is whole, but it cannot see battle until you have tempered it. That jagged saronite edge is brittle and will shatter the moment it strikes anything.\n\nDeep in Icecrown Citadel's Forge of Souls is a place where the blade can safely be tempered. Take Quel'Delar with you to the abode of the Devourer of Souls and look for the crucible. Plunge the blade into the crucible to temper it and bring it back to me in The Frozen Halls.", sourceObjective = "Temper the Reforged Quel'Delar in the Crucible of Souls.", progress = "Until the sword is tempered, it will be useless.", completion = "I... I don't understand. Tempering the sword should've restored the blade to its original condition. What has happened here?", sourceObjectiveStatus = "unverified-source-field" }
quests[24477] = { id = 24477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dwarven Artifacts", description = "{name}, my <boy/beautiful flower>!  Are you into archaeology?\n\nWe've an exciting opportunity right outside our front door.  All the shaking from today's seismic event has knocked a number of artifacts loose from the soil around our encampment.  Survey along the valley's northern border, and you should find all sorts of treasures.  Bring some back to me, and perhaps we can study them together.\n\nRight, then!  Off you go!", sourceObjective = "Obtain 5 Forgotten Dwarven Artifacts.", progress = "Yes?", completion = "Wonderful!  Look at this one... it must be over 200 years old!\n\nNow, onto other matters...", sourceObjectiveStatus = "unverified-source-field" }
quests[24478] = { id = 24478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trial of Frost", description = "You know, some of my apprentices have called me cold hearted. I always say though, I shall not let the temperature of my body parts stand in the way of true learning.\n\nTo reach the Trial of Frost, touch the Frost crystal to open a portal. Once there, the goal is quite simple - gather the little floaty ice orb thingies.\n\nTo counter the simple, the rotating Frostburns may put back your progress, as it were. If you want to be fancy, you can use the rune traps to jump over them as they rotate by. Neat, eh?", sourceObjective = "Complete the Trial of Frost by gathering 20 Essence of Ice without getting hit by Frostburn.", progress = "No. Just no. Do it right this time.", completion = "Brilliant. You certainly don't let cold feet stop you. Or cold any part for that matter!\n\nNo? ...too soon?", sourceObjectiveStatus = "unverified-source-field" }
quests[24479] = { id = 24479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trial of Shadow", description = "Let us not be confined by the bounds of the mage repertoire of magic. I, for one, choose not to be classist. Necromancy can just be so much fun!\n\nTouch the Shadow Crystal to open a portal to my Trial of Shadow. Once there, move to the Altar when you are ready to begin.\n\nWeeping Souls shall begin to pursue you... your goal is simply to drag them into the traps. And be sure not to let them touch you.", sourceObjective = "Complete the Trial of Shadow by luring 20 Weeping Souls into the shadow runes without getting touched.", progress = "You're not very good at this. You're supposed to complete the trial BEFORE you come talk to me again. Make sense?", completion = "I like the way you move, apprentice.\n\nDon't you worry about where I got all the souls from. They were obtained in a perfectly humane manner, I assure you.", sourceObjectiveStatus = "unverified-source-field" }
quests[24480] = { id = 24480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Halls Of Reflection", description = "You have reforged and tempered the sword, yet it sits quietly in its sheath, showing no signs of the power it should possess. You say the sword pulls you, as though it possesses a will?\n\nDare you bring it where it wishes to go? It's not right that the sword should be this silent and this insistent, yet I fear that if you do not take the sword to its destination, we will never learn why. Take it into Icecrown Citadel's Halls of Reflection, but be on your guard! I'll be waiting for you in The Frozen Halls.", sourceObjective = "Bring your Tempered Quel'Delar to Sword's Rest inside the Halls of Reflection.", progress = "What happened inside the Halls of Reflection?", completion = "I had not thought it possible for evil to take hold in such a sword, but I suppose it was naive of me. If the greatest of dragonkind's creations could be corrupted and turned against them, why not a mere sword?\n\nUther's advice is wise, {name}, and I would urge you to heed it quickly.", sourceObjectiveStatus = "unverified-source-field" }
quests[24483] = { id = 24483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormglen", description = "Our carriage drivers were told to regroup in the fishing town of Stormglen.  Our scouts report there might be shelter and supplies to be found there.\n\nMeet Gwen Armstead there, she'll be in charge of taking care of our people.", sourceObjective = "Speak to Gwen Armstead in Stormglen.", completion = "It's good to see you made it, {name}.  It looks like most everybody did.\n\nWe're not doing too bad so far for an emergency evacuation.", sourceObjectiveStatus = "unverified-source-field" }
quests[24484] = { id = 24484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pest Control", description = "Well, what do you know, {name}?  All this time and Stormglen's been left mostly intact.\n\nIt's too bad the Forsaken are still working their way inland, but it'll make a fine place to rest our feet for a night or two.\n\nThe other half of town is overrun with spiders, so I've asked the villagers to stay away from there.\n\nPerhaps you'd like to lend a hand in clearing the spiders out?  I'm certain our injured men and women will sleep more soundly if they know someone's keeping those eight-legged beasts at bay.", sourceObjective = "Kill 6 Vilebrood Skitterers in Stormglen.", progress = "You're back, {name}.  Have the spiders been taken care of?", completion = "You've done well, {name}.  The spiders are everywhere, however, and I'm afraid we've barely put a dent in their numbers.", sourceObjectiveStatus = "unverified-source-field" }
quests[24486] = { id = 24486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Hay While the Sun Shines", description = "The trogg village to the southwest suffered similar damage to ours.  One would assume, logically, that there would be some trogg artifacts sticking out of the ground, too!\n\nUnfortunately, it looks like most of the artifacts have already been scooped up by trogg scavengers.  Please, go see if you can find some way to get them back.  Believe it or not, knowledge about troggs may eventually lead to further knowledge about the mighty dwarves!", sourceObjective = "Obtain 5 Priceless Rockjaw Artifacts from Rockjaw Scavengers.", progress = "Did you manage to pry any artifacts from the troggs?", completion = "Well would you look at this!  An axe blade, a couple of arrowheads, and what appears to be some sort of rudimentary spoon.  This is indeed fascinating.\n\nThanks again for your help, {name}.  I've much studying to keep myself occupied while Joren's got us under lockdown.", sourceObjectiveStatus = "unverified-source-field" }
quests[24487] = { id = 24487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whitebeard Needs Ye", description = "Ye've done us a great service here, but I'm afraid I've gotta send ye off elsewhere.\n\nGrelin Whitebeard, a good friend of mine, has put in word that he may need some reinforcements near the troll camps to the southwest.  Follow the road westward, ye should find him soon enough.\n\nBe well, {name}.  Troggs may be a pain, but trolls are a whole other type of trouble.", sourceObjective = "Report to Grelin Whitebeard's camp in Coldridge Valley.", completion = "Welcome, {class}.  Are you ready to get to work?", sourceObjectiveStatus = "unverified-source-field" }
quests[24488] = { id = 24488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Replacements", description = "My guys are all on the injured roster! Our shredders are all kaput! The ref is about to call the game!\n\nIt's down to the wire and I need you, {name}!!!\n\nLet's get one of these shredders in working condition. There are replacement parts all over Bilgewater Port. Any green-blooded Kezanian will gladly let you have them if there's a chance that the Buccaneers will win.\n\nWe'll show those no-good Steamwheedle Sharks how to play footbomb!", sourceObjective = "Collect 6 Replacement Parts.", progress = "We're counting on you, {name}!", completion = "That's my boy! Now to get one of these useless hunks of metal in working order and you into the game!", sourceObjectiveStatus = "unverified-source-field" }
quests[24489] = { id = 24489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trolling for Information", description = "I'm notoriously bad at reading troll facial expressions.  That being said, these trolls don't look angry to me.  They seem to be confused... maybe a little frightened.\n\nSomething happened that we're not seeing here, {name}.  I say we do some investigation before we just kill every troll in sight.\n\nThere are three troll camps in the area: one to the southeast, one to the southwest, and one due west.  Each camp has a soothsayer... see if you can get close enough to listen to what they're saying.", sourceObjective = "Stand near a Frostmane Soothsayer in each of the Frostmane camps and listen to what they have to say.", progress = "I can't even begin to imagine what would make the trolls act like this.", completion = "Hmm... interesting.  From what you're saying, it sounds like a fire elemental might have snuck in from Searing Gorge.  Or, the earthquake opened up a crack to the elemental plane...\n\n<Soren laughs uncomfortably.>\n\nEither way, this is bad news.  You should probably report this information to Grelin.", sourceObjectiveStatus = "unverified-source-field" }
quests[24490] = { id = 24490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Trip to Ironforge", description = "The presence of a fire elemental here in Coldridge is no small matter.  That earthquake did more than just upset a bunch of troggs... it changed the world enough to tear a gash into the elemental plane.  We should submit a report to Ironforge.\n\nYou wouldn't be willing to take a trip, would ya?  Don't worry, I've a feeling that you'll do just fine.  Talk to Hands Springsprocket by the tunnel on the eastern edge of the valley.  He'll point you in the right direction.", sourceObjective = "Report to Hands Springsprocket in Coldridge Valley.", completion = "To Ironforge?  Well first, you'll need to go through Kharanos, and before that, you'll have to go through this tunnel.", sourceObjectiveStatus = "unverified-source-field" }
quests[24491] = { id = 24491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Follow that Gyro-Copter!", description = "D-d-did you see that?  How the whole cave just crumbled like that?  I guess it's good that you got here when you did, and not a minute earlier.\n\nWhile this development makes my job of monitoring the cave entrance much easier, I imagine it makes it a lot harder for you to get to Kharanos.\n\nHey wait, I've got an idea!  The Gnomeregan Airmen have a flight path not far from here.  I'll send up a signal, and they should be here to help.  I imagine they'll land back over at Anvilmar.", sourceObjective = "Report to Milo Geartwinge near Anvilmar.", completion = "Milo Geartwinge, reporting for duty.  You sent up a distress signal?", sourceObjectiveStatus = "unverified-source-field" }
quests[24492] = { id = 24492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pack Your Bags", description = "The weight limit on my gyro is such that I only have enough room for one {race}.  Looks like you're in luck, {name}!\n\nThat dwarf woman Jona told me that most of your personal belongings have been moved inside Anvilmar.  Please gather what you'll need, finish up any affairs that remain, and return to me when you're prepared for takeoff.", sourceObjective = "Obtain a Coldridge Beer Flagon, a Ragged Wolf-Hide Cloak, and some Leftover Boar Meat.", progress = "Are you absolutely certain you've taken care of everything?  You won't have time to turn back.", completion = "Took you long enough.  Hold on tight, and take a good hard look!  Chances are you won't be coming back here for quite some time.", sourceObjectiveStatus = "unverified-source-field" }
quests[24493] = { id = 24493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Forget About Us", description = "You're leaving?  Make sure you stock up before you head out.\n\nMore importantly, please speak to Tharek Blackstone once you arrive in Kharanos.  Tell him what has happened here in Coldridge, and that we could use some assistance.  Hopefully he'll be able to arrange something for us.", sourceObjective = "Report to Tharek Blackstone in Kharanos.", completion = "Coldridge Valley?  I've got my own problems here!  What, they can't deal with a couple of troggs?  And trolls?  And incursions from the elemental plane?\n\nActually, on second thought, that's kind of a lot.  I'm surprised they're doing as well as they are.  I'll see what I can do.", sourceObjectiveStatus = "unverified-source-field" }
quests[24494] = { id = 24494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empowered Rune", description = "{name}, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I'm thinkin' it came from the shaman trainer Teo. Take a gander at it and go find him inside Anvilmar.", sourceObjective = "Read the Empowered Rune and speak to Teo Hammerstorm in Anvilmar.", progress = "The spirits have forewarned me of your arrival, {name}.  Have you heard them too?", completion = "These are dark days, friend.  Look around you... even here in remote Coldridge, the spirits are rebelling.  The land is crying out for help.  Yet still, even in times such as these, the spirits will always turn an ear to those who ask for their assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[24495] = { id = 24495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pieces of the Past", description = "I found a journal by a man named Bradshaw.  Unfortunately it's missing many pages.  Especially towards the end.\n\nIf you find enough of the pages I might be able to piece together what happened here after the Curse broke out.\n\nWho knows... maybe the people in this town found a way out.   Maybe there are still survivors out there.\n\n Maybe my father is still alive.", sourceObjective = "Obtain 6 Old Journal Pages.", progress = "Any luck finding those pages?", completion = "Thank you, {name}.  It will take some time, but I'll try to make sense of what we have.", sourceObjectiveStatus = "unverified-source-field" }
quests[24496] = { id = 24496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Rune", description = "{name}, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I'm thinkin' it came from the mage trainer Teegli. Take a gander at it and go find her inside Anvilmar.", sourceObjective = "Read the Arcane Rune and speak to Teegli Merrowith in Coldridge Valley.", progress = "I see that Jona's given you my runic message.  Do you still have it with you?", completion = "The power of the arcane is everywhere, {name}.  Only some of us have the ability to see it, and fewer still possess the ability to master it.\n\nYou are one of those few.", sourceObjectiveStatus = "unverified-source-field" }
quests[24497] = { id = 24497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Airborne Again", description = "We just got word from Valormok that we can't send anymore windriders that way unless we want them shot down by Talrendis snipers. We can't give up Valormok if we want a secure route to Ashenvale, so we're going in another way.\n\nThe airborne priests have graciously offered to drop some people in for us from above sniper range. Head up to the military area and secure a ride on one of their planes. They'll get you there in one piece, and hopefully once you're there, you can resecure our windrider lines.", sourceObjective = "Secure a ride to Valormok with the Airborne Priests in the eastern portion of Bilgewater Harbor.", completion = "It's past time that these night elf scum be purged from Azshara. Glad to have an able body like you to sink the point home.\n\nReady to get to work?", sourceObjectiveStatus = "unverified-source-field" }
quests[24498] = { id = 24498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path to the Citadel", description = "They've put our captured soldiers to work in the quarry!\n\nKill their captors and set them free, hero. We will need their aid when we confront Scourgelord Tyrannus.", sourceObjective = "Free 15 Alliance Slaves and kill Forgemaster Garfrost.", progress = "My men and I appreciate your help, {class}. More than we could possibly express in these trying times.", completion = "You've done well this day. With many of the slaves freed and now with access to the forges, it will not be long before I have a strong force to aid in delivering us from Scourgelord Tyrannus and this foul pit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24499] = { id = 24499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes of Tortured Souls", description = "We're severely undermanned to be risking a venture into the citadel, but opportunities like this are too rare to pass up.\n\nClear the way to the far side and secure the passage to the Pit of Saron. We will need to hold it to move our men further into the citadel.", sourceObjective = "Kill Bronjahm and the Devourer of Souls to secure access to the Pit of Saron.", completion = "Just in time! Thank you, {name}.\n\nThe Pit of Saron lies ahead, and if our scouts are correct, past that will be the Halls of Reflection. It is there that Arthas lets his guard down, and it is there that we hope to find a clue to his weakness... or maybe, just maybe, his redemption.", sourceObjectiveStatus = "unverified-source-field" }
quests[24500] = { id = 24500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Lich King", description = "It's hard to believe that there is much hope of defeating Arthas upon the steps of his own throne. And who will take up the crown of Lich King if it comes to that?\n\nMany questions remain. but you need to find Jaina and escape the Lich King while there's still time.", sourceObjective = "Find Lady Jaina Proudmoore and escape the Halls of Reflection.", completion = "<Jaina is still catching her breath.>\n\nI can barely believe we're still alive. It was foolish of me to follow him. I've made that mistake too many times.  And you... it was reckless of you to come after me instead of escaping with the information! But... well... thank you. You truly are a hero.\n\nWith Uther's guidance, we may stand a chance at defeating Arthas. All the lives lost today were not in vain.", sourceObjectiveStatus = "unverified-source-field" }
quests[24501] = { id = 24501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Queen-Sized Troubles", description = "The spiders keep coming in alarming numbers, {name}.  You're going to have to go into their lair and kill the broodmother.\n\nWe've spotted the giant spider known as Rygna at the edge of the Blackwald in an area covered in thick webs.  It'll be dangerous, but we're all counting on you.", sourceObjective = "Slay Rygna at Rygna's Lair.", progress = "Did you take care of Rygna, {name}?", completion = "Great job, {name}.  We've heard rumors of survivors further in the mountains.  Now we'll be able to send scouts there.", sourceObjectiveStatus = "unverified-source-field" }
quests[24502] = { id = 24502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necessary Roughness", description = "We're down to our last shredder. While no one was looking, I loaded it up with, shall we say, modified footbombs.\n\nKid, I need you to get in that shredder and give 'em heck!", sourceObjective = "Get into the Bilgewater Buccaneer and then throw the Footbomb at 8 Steamwheedle Sharks.", sourceObjectiveStatus = "unverified-source-field" }
quests[24503] = { id = 24503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fourth and Goal", description = "It's all up to you, kid. You demolished the Steamwheedle Sharks, so now all that's left to do is to kick the winning goal.\n\nNow, just between you and me, I think we should do this one right. I don't want you to just kick a goal... I want you to kick it so far it sails between the two smokestacks behind the goal!\n\nI've modified the footbomb to give you the extra power that you'll need.\n\nMake me proud!", sourceObjective = "Score the winning goal by kicking the Footbomb through the smokestacks behind the opposing goal.", completion = "Uh... you did it, kid. You REALLY did it! We won the game and....\n\nDID YOU SEE THAT DRAGON?!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[24504] = { id = 24504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear the High Road", description = "This way, {class}! I see you've discovered the high road.\n\nThe Alliance hopes to sever our ties with Stonetalon, but they forget that we tauren have hunted across these lands for generations. We know every hillside switchback and game trail from here to Thousand Needles.\n\nBut for these paths to stay open, we must stop the humans from mapping them out.\n\nPatrol the trail east and kill any high road scouts you find along the way, then speak to Tunawa Stillwind just up the path.", sourceObjective = "Slay 3 High Road Scouts.", completion = "Patrolling the high road is grave business, but it must be done. These narrow mountain trails are, for the time being, one of our only lifelines into Stonetalon. They must be preserved.\n\nThank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[24505] = { id = 24505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holdout at Hunter's Hill", description = "Honor's Stand may have been lost, but its spirit was never crushed. Even now survivors are holding out at a point called \"Hunter's Hill.\"\n\nContinue following the high road and you will find our camp just up ahead. Speak with Onatay when you get there and let her know the trail is, for the moment, still clear.", sourceObjective = "Speak with Onatay at Hunter's Hill in Southern Barrens.", completion = "So the Alliance is probing the twists and turns of the high road?\n\nEven if they were to map it out, they couldn't attack these hills in numbers. This is our land, {name}. And they will pay dearly for presuming otherwise.", sourceObjectiveStatus = "unverified-source-field" }
quests[24506] = { id = 24506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inside the Frozen Citadel", description = "{class}! Come close quickly, I must have a word!\n\nMy queen, the Lady Sylvanas Windrunner, has uncovered a hole in the defenses of Icecrown Citadel into a place she referred to as \"The Forge of Souls.\" She sent word before she left for me to find fierce fighters to send her way. I think you'll do.\n\nGo to her within the entrance to the forge, {class}.", sourceObjective = "Enter The Forge of Souls from the side of Icecrown Citadel and locate Lady Sylvanas Windrunner.", completion = "Good. {name}, I know of you. You'll be perfect for these tasks.\n\nWe've been afforded a rare chance to delve into Icecrown Citadel, but we must move quickly if we're to avoid Arthas' notice.", sourceObjectiveStatus = "unverified-source-field" }
quests[24507] = { id = 24507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path to the Citadel", description = "They've put our captured soldiers to work in the quarry.\n\nKill their captors and set them free, {class}. We will need their aid when we confront Scourgelord Tyrannus.", sourceObjective = "Free 15 Horde Slaves and kill Forgemaster Garfrost.", progress = "Thank you, {class}. You will have our blood and our steel behind you this day.", completion = "You've done well this day. With many of the slaves freed and now with access to the forges, it will not be long before I have a strong force to aid in delivering us from Scourgelord Tyrannus and this foul pit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24508] = { id = 24508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temp Quest Record" }
quests[24509] = { id = 24509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temp Quest Record" }
quests[24510] = { id = 24510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inside the Frozen Citadel", description = "{class}! Come close quickly, I must have a word!\n\nMy patron, the Lady Jaina Proudmoore, has uncovered a hole in the defenses of Icecrown Citadel into a place she referred to as \"The Forge of Souls.\" She sent word before she left for me to find any help that I could... and, well, I was hoping that might be you.\n\nPlease, find her there as soon as you can.", sourceObjective = "Enter The Forge of Souls from the side of Icecrown Citadel and find Lady Jaina Proudmoore.", completion = "{name}! I'm so glad you've come.\n\nWe've been afforded a rare chance to delve into Icecrown Citadel, but we must move quickly if we're to avoid Arthas' notice.", sourceObjectiveStatus = "unverified-source-field" }
quests[24511] = { id = 24511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes of Tortured Souls", description = "Delving into the citadel with so few is risky at best, but opportunities like this are too rare to pass up.\n\nClear the way to the far side and secure the passage to the Pit of Saron. We will need to hold it to move our men further into the Citadel.", sourceObjective = "Kill Bronjahm and the Devourer of Souls to secure access to the Pit of Saron.", completion = "Well timed, {class}!\n\nThe Pit of Saron lies ahead, and if our scouts are correct, past that will be the Halls of Reflection. It is there that Arthas lets his guard down, and it is there that we hope to find a clue to his weakness... and a route to vengeance long overdue.", sourceObjectiveStatus = "unverified-source-field" }
quests[24512] = { id = 24512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warriors' Redemption", description = "Those that surrendered when Honor's Stand fell are no longer worthy of our Horde, {class}. But I'm not giving up on them yet. The prison tower below us is lightly guarded. Let's give those prisoners one final chance to die with honor.\n\nI've set up ropes that will allow you to quickly clamber up and down the mountain. Slip down, acquire the confiscated weapons, and re-arm the prisoners inside the tower.\n\nAnd {name}, stay by the tower! We're not yet equipped for an assault on the base proper.", sourceObjective = "Acquire 5 crates of Confiscated Arms from Honor's Stand and re-equip 5 Stonetalon Prisoners. Use the nearby ropes to quickly sneak in and out of the Alliance camp.", completion = "From up here I got the perfect view of the havoc you just caused, {name}. Our lost brothers reclaimed some of their dignity, and the Alliance dogs were sent scrambling. Sharp work, my friend!\n\nIf the Alliance sleeps comfortably at night, we are not doing our job.\n\nWe will never let up.\n\nWe will never give in.", sourceObjectiveStatus = "unverified-source-field" }
quests[24513] = { id = 24513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye for an Eye", description = "Who goes there? Your footsteps are not the lazy stride of a guard.\n\nA {class}, you say? Still brave and free? There's no hope for me, friend. I have lost my eyesight and am no longer fit for battle.\n\nI dared speak up while Captain Peake savagely beat one of the prisoners. In return he kicked me in the head. And kept kicking. He kicked me blind, {race}.\n\nYou'll find Captain Peake at the top of this tower. If you seek justice, bring me his eyes.\n\nIf he does not part with them willingly... so be it.", sourceObjective = "Slay Captain Peake and deliver his eyes to Oltarg.", progress = "Peake is a monster. If his superiors knew, they would thank the Horde for ending him.", completion = "You have them? I'll take your word for it. Hearing Peake scream like one of his victims is reward enough for me.\n\nNow leave me be, {name}. I do not wish to be a burden to my clan.", sourceObjectiveStatus = "unverified-source-field" }
quests[24514] = { id = 24514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptor Scraps", description = "We are besieged here, {class}, and between that chasm and the harassment of the Alliance we are short on supplies. But we make do with what's at hand, as we tauren always have.\n\nIn the absence of a forge, a skilled leatherworker can strengthen and patch up our damaged armor with good quality hides.\n\nDown below is the hunting ground of the Terrortooth Raptors. They are not so easy to kill, in part due to the ruggedness of their thick skin. Hunt them, {name}, and bring their hides to me!", sourceObjective = "Gather 8 Terrortooth Hides from Terrortooth Runners and Terrortooth Scytheclaws.", progress = "Terrortooth raptors hunt in packs and surround their prey. We hunt them, yes; but we also respect them.", completion = "<Onatay looks over the fresh hides, nodding her head slowly.>\n\nYes {name}, I can work with these. You work fast!\n\nThese hides will help us hold out for reinforcements longer. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[24515] = { id = 24515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signals in the Sky", description = "Turn your eyes to the southeast. Do you see the campfire smoke from Camp Una'fe?\n\nNot ten minutes ago I saw great puffs of white smoke roll up into the sky from the center of camp. It was an old signal used by my village to coordinate the hunt over great distances, but this time, it was a distress signal.\n\n{name}, my brother Makaba had gone into that unnatural jungle. Please go there and make sure he's not in any trouble.\n\nThere are few paths: look for tents within the wilderness.", sourceObjective = "Travel to Camp Una'fe in the Overgrowth of Southern Barrens and speak with Makaba Flathoof.", completion = "So my sister recognized the old signals? Her hunter's eyes are as sharp as ever.\n\n{name}, when we first set up this camp we were at the edge of this jungle. Now look at it!\n\nSomething is amiss.", sourceObjectiveStatus = "unverified-source-field" }
quests[24517] = { id = 24517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put the Fear in Them", description = "Do you see the trail below us, {name}? That is MY trail. And if the Alliance dogs choose to use my trail, they'd best be looking over their shoulder.\n\nIt's time to collect my toll! Slay the footsoldiers from Honor's Stand and see if we can't send them scurrying back to their walls.\n\nBe sure to take out at least one of their officers patrolling the road. They need to realize that nobody is safe.", sourceObjective = "Kill 8 Honor's Stand Footmen and 1 Honor's Stand Officer.", completion = "Excellent, {name}. It will be some time before we can assault the hold proper, but until then, we must teach them to fear the Barrens.", sourceObjectiveStatus = "unverified-source-field" }
quests[24518] = { id = 24518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Low Road", description = "This bundle of papers was found in a leather satchel hidden under the officer's clothes.\n\nBattle maps of the region depict Honor's Stand, connected to what appears to be a large unfinished roadway crossing the Barrens all the way from Theramore. It looks like the Alliance plans to build a road from the coast straight into the heart of Kalimdor!\n\nKilrok Gorehammer will want to see this.", sourceObjective = "Deliver the Roadway Plans to Kilrok Gorehammer at Hunter's Hill in Southern Barrens.", progress = "Ah, you say you found something on one of the bodies?", completion = "<Kilrok pages through the plans you discovered.>\n\nThis explains much, {name}. No wonder our foes are so hellbent on taking the southern Barrens. It's at the center of their plans for the continent!\n\nBut they didn't account for us, did they {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[24519] = { id = 24519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalling the Survey", description = "These maps have all been drawn by the same steady hand. I've seen a human surveyor heading up and down the road between the hold and the jungle to the east.\n\nWe can set their plans back by making an example out of this surveyor, {name}.\n\n<Kilrok points to the signature at the bottom of the maps.>\n\nWhat do you think that says? \"Zykes?\" Even human names sound thin and weak. Kill him.", sourceObjective = "Find and kill the surveyor Henry Zykes.", completion = "Good, good. We've got to keep Honor's Stand isolated.\n\nAlone ... afraid ... {name}, if we keep up the pressure, maybe someday they'll simply surrender the pass.", sourceObjectiveStatus = "unverified-source-field" }
quests[24520] = { id = 24520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Give Sassy the News", description = "I'd celebrate with you, {name}, but it feels like that dragon did a number on ol' Mount Kajaro. I... uh... I think I'm gonna grab my stuff and get on the first ship leaving the island!\n\nAnyways, you should probably head back to headquarters and let Sassy know that you won the footbomb title for us. I'm sure she'll also want to know about the dragon and Mount Kajaro.\n\nGood luck!", sourceObjective = "Speak with Sassy Hardwrench at KTC Headquarters on Kezan.", completion = "You're kidding, right?! DEATHWING?!!!\n\n<Sassy looks panicked for a moment.>\n\nOkay, this'll work out just fine. We'll throw your party and by the time it's over, I'm sure that the dragon will be long gone and the ground will stop shaking.\n\nIf not, we can always charter a ship off of the island.", sourceObjectiveStatus = "unverified-source-field" }
quests[24522] = { id = 24522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey To The Sunwell", description = "Take Quel'Delar to the Sunwell as quickly as possible, {name}. Trust in Uther's words when he says that you will not always be able to control the blade while it is subject to the evil of the Lich King's influence. You must travel to the Isle of Quel'Danas, and there, seek entry to the Sunwell itself, where you can cleanse the sword.\n\nThe guardians of the Sunwell will not simply allow you to walk in, so you must find Halduron Brightwing, who will be inspecting the guards there.", sourceObjective = "Speak with Halduron Brightwing at the entrance to the Sunwell Plateau on the Isle of Quel'Danas.", progress = "What brings you here?", completion = "Admit you to the Sunwell? That's impossible! The Sunwell is the most sacred and important site of our people. We have only recently reclaimed it with the help of the Shattered Sun Offensive. It is not a place for tourists or travelers.", sourceObjectiveStatus = "unverified-source-field" }
quests[24523] = { id = 24523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildmane Totem", description = "There is but one water well left to cleanse, named after the Wildmane clan.  For this well to be pure, the land must offer the teeth of a fierce predator, the prairie wolf alpha.  Find the alphas to the north, then return to me when your hunt is finished.\n\nAlphas often wander around the base of our mighty city, Thunder Bluff.", sourceObjective = "Collect 4 Prairie Alpha Teeth from Prairie Wolf Alphas.", progress = "{name}.  Do you have the teeth I asked for?", completion = "Very good, {name}.  I can feel the sacrifice of the land in this offering, and my spirit swells with sadness, and pride.", sourceObjectiveStatus = "unverified-source-field" }
quests[24524] = { id = 24524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildmane Cleansing", description = "Your cleansing of the Winterhoof and Thunderhorn wells is spoken among the spirits, young {name}.  The Wildmane Totem is made, and your last task lies ahead.\n\nThe Wildmane Water Well lies north of Thunder Bluff.  Perform the ritual!  Heal the land of the Grimtotem's poisons!  Let clean water flow once again!", sourceObjective = "Use the Wildmane Cleansing Totem at the Wildmane Water Well.", completion = "You've done it.  You have cleaned the wells, and healed our land.  Bloodhoof village is grateful, {name}.\n\nMay the wind whisper your deeds for a hundred seasons, and may the waters of Mulgore remain clean forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[24525] = { id = 24525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping the Dogs at Bay", description = "Not everyone who fled Taurajo was able to make it to Una'fe, {name}. Some died of wounds along the way. Others were jumped by opportunistic quilboar.\n\nI'll take care of the grim task of finding and gathering the bodies. But there is something you can do for me.\n\nHecklefang scavengers prowl the lands south of here and are savaging the corpses, tearing at their bowels and dragging away the limbs of the dead. Please, thin their numbers so that I can perform the proper funerary rites.", sourceObjective = "Kill 6 Hecklefang Scavengers.", completion = "So it is done.\n\nNormally these scavengers are part of the Earthmother's cycle of life. But on the heels of the devastation wracked by both the Alliance and the cataclysm, their numbers grow overwhelming. It is good to thin them out.", sourceObjectiveStatus = "unverified-source-field" }
quests[24526] = { id = 24526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filling Up the Spellbook", description = "Excellent!  Let's get started.\n\nFirst, you're going to have to learn the spell Arcane Missiles.  This spell is a little bit different from others you've learned in the past. Each time you cast another spell, you have a chance to create an opening to use Arcane Missiles.  Why not get a feel for the spell using those training dummies the militia trainees put up outside the entrance to Anvilmar?", sourceObjective = "Learn Arcane Missiles from Teegli Merrowith. Successfully cast Arcane Missiles 2 times on the Training Dummies outside the entrance to Anvilmar.", completion = "There we go!  One spell down, many many more to go.  Come back to me after you've had some experience casting this spell, and I'll show you some more tricks.", sourceObjectiveStatus = "unverified-source-field" }
quests[24527] = { id = 24527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Path Begins Here", description = "Excellent!  Let us begin.\n\nThe first skill you will learn is that of the Primal Strike.  The primal spirits, when called upon, will strengthen your arm to deliver a mighty blow.\n\nHelpful, isn't it?", sourceObjective = "Learn Primal Strike from Teo Hammerstorm, then use Primal Strike 2 times on a Training Dummy near the entrance of Anvilmar.", completion = "This has been but one of many footfalls on the long path of the {class}.  Come back to me after you've had some experience in the field, and I will help guide you on your next step.", sourceObjectiveStatus = "unverified-source-field" }
quests[24528] = { id = 24528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of the Light", description = "Are ya ready to start?  Wonderful!  We're glad to have ya.\n\nBefore ya go back outside, I'm gonna need ya to learn the Seal of Righteousness.  It will grant Holy damage to your swings, helping ya dispatch yer enemies quicker.\n\nThe other thing yer gonna want to know is that any time ya have a seal active, ya can use the light to judge yer enemies. Yer judgement will deal damage each time ye invoke it.", sourceObjective = "Learn Seal of Righteousness and Judgment from Bromos Grummner. After casting Seal of Righteousness on yourself, use Judgment on one of the Training Dummies at the entrance to Anvilmar.", progress = "Seal of Righteousness is great! I feel righteous right now!", completion = "There, ya did it.  The Light favors quick learners like you.  Come back to me after you've spent some time using what I've taught ya, and I'll show ya something new.", sourceObjectiveStatus = "unverified-source-field" }
quests[24529] = { id = 24529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad to Worse", description = "When the refugees fled north from Taurajo, some were separated as darkness closed in. Many were taken prisoner by the Bristleback quilboar who set up camp west and southwest of here.\n\nI am not certain what the quilboar hoped to get from us by capturing our refugees; all they have earned is my ire. And all they'll get in return is vengeance.\n\nRescue my trapped brothers and sisters, and kill their captors to send a message to the quilboar.", sourceObjective = "Rescue 5 caged Taurajo Refugees, and kill any combination of 8 Bristleback Thornweavers or Bladewardens.", completion = "It's bad enough to have one's village sacked... but to spend the following night in a quilboar cage? I'm glad you were there to help, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24530] = { id = 24530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, A Hunter's Life For Me", description = "The life of a hunter is steeped in tradition, ye know.  Trackin' mighty beasts through rugged terrain.  Drinkin'.  Travelin' the land, yer gun at yer side.  Drinkin'.  Survivin' on wits and courage and cunning, followed by a good stiff drink.\n\nBut before we get to the good stuff, though, ye'll need to learn how to do the beginner stuff.", sourceObjective = "Learn Steady Shot from Thorgas Grimson, then use Steady Shot 5 times on the Training Dummies outside the entrance to Anvilmar.", progress = "I know the {class}'s life is exctin' now, but you jus' wait... it gets even better.", completion = "Now that ye've got a new {class} trick under yer belt, and now that I've got some of yer money, go out there an' track some beasts!  Come back sometime in the future, an' we'll talk again.", sourceObjectiveStatus = "unverified-source-field" }
quests[24531] = { id = 24531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting Battle-Ready", description = "Lesson one.  Aside from your sword and shield, what's the most important tool you have in your arsenal?\n\n<Thran awaits your response.>\n\nOh never mind, I'll answer it for you.  It's your mobility.  One of the strengths of the warrior is the ability to get around the battlefield quickly.  Here, {name}, I'll train you to use your legs to your advantage.", sourceObjective = "Learn Charge from Thran Khorman, then use Charge on one of the Training Dummies outside the entrance to Anvilmar.", completion = "Now we're getting somewhere.  You've got quite a manly bellow, sir!\n\nCome back to me in a bit, and I'll teach you something else.", sourceObjectiveStatus = "unverified-source-field" }
quests[24532] = { id = 24532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evisceratin' the Enemy", description = "One of the things that makes a rogue dangerous is our ability to use combinations of combat maneuvers and wait for the chance to use a devastating technique.\n\nNow that you've had a chance to master Sinister Strike, it's time to show you a new skill you can use as a follow up.\n\nPlease, allow me to train you.", sourceObjective = "Learn Evisecerate from Solm Hargrin, then use Eviscerate 3 times on the Training Dummies near the entrance to Anvilmar.", progress = "No, this isn't just my way of getting your money.  I'm doing this for your own good.\n\nReally.", completion = "You've got the hang of it.  Go get some practice out there... maybe take out a few of those troggs or trolls.  Or rabbits, I don't care.\n\nReturn after you've gotten some practice, and I'll show you another trick of the trade.", sourceObjectiveStatus = "unverified-source-field" }
quests[24533] = { id = 24533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words of Power", sourceObjective = "Learn Flash Heal from Branstock Khalder, then cast Flash Heal 5 times on Wounded Militia members in Anvilmar.", completion = "Well done, {name}.  You'll make a fine {class} in due time.\n\nReturn to me after you've proven yourself a bit more, and I'll reward you by teaching you another spell or two.", sourceObjectiveStatus = "unverified-source-field" }
quests[24534] = { id = 24534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speaking Their Language", description = "The quilboar are attacking because they perceive weakness. Strength is the only language they understand. So we will show them strength.\n\n<Makaba withdraws a large horn from his satchel.>\n\nThis is admittedly crude work but it'll do. Bristleback leaders use horns like these to challenge one another for dominance.\n\n{name}, I want you to challenge the Bristleback champion, Sabersnout, to single combat. Defeat him in front of his followers. Blow the horn at the Bristleback challenge ring due south of here.", sourceObjective = "Blow the Horn of Challenge in the Bristleback Challenge Ring, and defeat Sabersnout in single combat.", progress = "Have you taken the Bristlebacks down a peg or two?", completion = "What? He attacked you with a dozen boars? I guess quilboar have their own ideas of what \"single combat\" means.\n\nStill, the Bristleback will be left reeling after the blow you delivered. It will not be long before a new champion rises amongst them to stir up trouble... but at least this buys us some time to get these refugees relocated safely.\n\nThank you, {name}. The survivors owe you a great debt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24535] = { id = 24535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thalorien Dawnseeker", description = "If you truly bear Quel'Delar, {name}, I might be able to admit you to the Sunwell. If you know the blade's history, you recall that it was borne by Thalorien Dawnseeker in defense of the Sunwell against the Scourge. He fell in what is now the Dead Scar, buying time for his men to make their own preparations. You will find his remains near the southern end of the Dead Scar on this isle. Visit them, and if his spirit gives you its blessing, I will allow you to enter the Sunwell.", sourceObjective = "Visit Thalorien Dawnseeker's Remains and obtain his blessing to wield Quel'Delar.", progress = "Did you visit the ground where Thalorien fell defending the Sunwell?", completion = "I confess that I did not expect Thalorien's spirit to recognize you as the heir to Quel'Delar, but I defer to his judgment. You may enter the Sunwell, but I remind you that you are a guest in the most our most sacred of precincts, and you should act accordingly.", sourceObjectiveStatus = "unverified-source-field" }
quests[24536] = { id = 24536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Stinks", description = "Get a load of these guys, would ya? Steamwheedle's been handling the business of holidays for years, and all of a sudden, these guys bust into the market. They're not Steamwheedle; the cartel hired me to get to the bottom of this. Something stinks here and it ain't just perfume.\n\nTake this device I brought and go analyze the perfume clouds around the guards. I want to know what they're putting in that stuff. Things ain't natural.", sourceObjective = "Use Snagglebolt's Air Analyzer to test the air around 6 heavily perfumed guards, then return to Detective Snap Snagglebolt in Orgrimmar.", progress = "You analyze that reek yet, kid?", completion = "Hey, thanks, kid. Give it over, let's take a look.\n\n<He takes the device from you and fiddles with it.>\n\nOh, that ain't good.", sourceObjectiveStatus = "unverified-source-field" }
quests[24539] = { id = 24539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Plants Attack", description = "This camp was built at the edge of this jungle, and already it is overwhelmed by plant growth. Something unnatural is happening here!\n\nEarlier I made the mistake of sending some of the healthier refugees out to gather nuts and berries. Those that returned talked about the plant life actually grasping at their legs or even picking them up. I worry about those that haven't come back yet.\n\n{class}, please rescue the refugees trapped in the grasping overgrowth around the camp.", sourceObjective = "Rescue 5 Taurajo Refugees by killing the Grasping Overgrowths that ensnare them.", completion = "Thank you, {name}. But now on to the larger question:\n\nWhere is this overgrowth coming from? And why is it raging out of control?", sourceObjectiveStatus = "unverified-source-field" }
quests[24540] = { id = 24540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Dance", description = "Some see our people as gentle giants, or noble savages. They have never seen us fight against our own kind...against betrayers from within.\n\nThe Grimtotem were offered mercy in exile, and they have scarred their own home to spite us. They will no longer be tolerated in Mulgore.\n\nI've already sent our warriors ahead to drive them out through Stonetalon Pass, to the north. You have fought bravely against the Grimtotem, {name}; I ask that you join the battle again. Go, and help deal this final blow.", sourceObjective = "Defeat Orno Grimtotem at Stonetalon Pass.", completion = "Welcome back, {name}.\n\n\n\nWhat was done was not for revenge, or pride. It was simply to protect Thunder Bluff, and all our people, from torment and fear. Today, Mulgore is safe once more.\n\nThe Earth Mother thanks you for all your brave deeds, {name}, as do I. You have earned your reward, hero. May you be welcome in Thunder Bluff always.", sourceObjectiveStatus = "unverified-source-field" }
quests[24541] = { id = 24541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilfering Perfume", description = "I knew they were up to no good! There's some sort of mind-affecting chemical in here, but I can't get a handle on it with such a small sample. I need the real stuff.\n\nDon't just go over there and buy it! I don't want you giving these scumbags one copper. Nah, you gotta get it from the source, discreet-like.\n\nI'll disguise you as a package runner. I saw a stockpile guarded by their goons outside the gates. Go run by, and DON'T stop, or they'll make you! They'll toss you a crate. Bring it back here.", sourceObjective = "While disguised as a package-runner, go to the Crown Chemical Company's stockpile outside the gates of Orgrimmar, then return the package they toss you to Detective Snap Snagglebolt in Orgimmar.", progress = "Did they toss ya a crate to deliver?", completion = "You got it, huh? Good job, kid. Top notch. Let's see what we got here.\n\n<He cracks open the crate and rummages around inside.>", sourceObjectiveStatus = "unverified-source-field" }
quests[24542] = { id = 24542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Curious Bloom", description = "The great archdruid Naralex recently appeared here in the Barrens. He's either behind this mess or trying to fix it. Either way, you should talk with him before this jungle engulfs the whole world! He's in a small tauren camp to the southeast.\n\nAlong the way, it would be helpful for you to gather plant samples for him to study. The newest flower buds will tell him a great deal about the most recent changes in the jungle.", sourceObjective = "Gather ten Unusual Flower Buds from Budding Flowers in the Overgrowth.", progress = "I am extremely busy, {class}.", completion = "Ah, samples from different parts of the overgrowth? These will be immensely helpful, yes. Thank you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24543] = { id = 24543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Family Divided", description = "The children you see here were all rescued from Taurajo when the fighting started. I'm trying to track down their parents.\n\nOne of the refugees you rescued from the quilboar recognized the strongest child as belonging to Kirge and Mawre Sternhorn. Moreover, he said Kirge was camped at the Fields of Blood, just north of the Taurajo massacre site.\n\n{name}, please go there and tell Kirge Sternhorn that his child is alive and well!", sourceObjective = "Find Kirge Sternhorn at Vendetta Point in Southern Barrens.", completion = "<Kirge listens intently and then falls to one knee.>\n\nAlive! My boy still lives! Praise to the earthmother, I still have a son.\n\n<Kirge composes himself.>\n\n{class}, my boy's mother didn't make it out of Taurajo alive. I will avenge her death, even if it means my son grows up without either of his parents.", sourceObjectiveStatus = "unverified-source-field" }
quests[24545] = { id = 24545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sacred and the Corrupt", description = "It is against my judgment that I present you this errand, {race}, as it will likely end in your undoing.\n\nIgnore my counsel and embark on the endeavor, and I shall provide you with the knowledge and resources to see it through.\n\nYou must return to Frostmourne Cavern and recover Light's Vengeance, Arthas' discarded hammer. Reforged with saronite and etched with the acidic blood of the Lich King's abominations, it will provide the foundation for our work.", sourceObjective = "Place Light's Vengeance, 25 Primordial Saronite, Rotface's Acidic Blood, and Festergut's Acidic Blood in Highlord Mograine's runeforge in Icecrown Citadel.\n\nRotface's Acidic Blood and Festergut's Acidic Blood may only be obtained in the 25 person difficulty setting of Icecrown Citadel.", progress = "As you draw near, the forge's flame seems to burn even more ravenously...", completion = "A deep sense of dread washes over you as the flame devours the items.", sourceObjectiveStatus = "unverified-source-field" }
quests[24546] = { id = 24546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Line in the Dirt", description = "The Alliance scorches a trail of murder across the Barrens. We must stop them here or there is nothing left for us.\n\nAcross the Fields of Blood there are a number of strategic hills, marked by wooden towers and neutral gray banners. We must take and hold these hills if we hope to slow the Alliance advance!\n\nLook for the towers to the north, east, and south of what's left of Taurajo. Claim a neutral flag and defend the hill against counterattack!", sourceObjective = "Capture a neutral hill in the Fields of Blood and defend it against an Alliance counterattack.", completion = "So you held your ground! With tenacity like yours we may yet drive the Alliance from our lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[24547] = { id = 24547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Feast of Souls", description = "Shadow's Edge is among the greatest weapons a {class} could hope to obtain.\n\nIs your lust for power sated, {race}?\n\n<You feel Mograine's penetrating gaze.>\n\nI thought not. A final warning then...\n\nYou now embark on the most treacherous leg of your quest. Bridle your aspirations, for if your aims are impure then your life, your very soul, is forfeit.\n\nThe weapon you hold is but an empty husk, a mere shadow of what it may become.", sourceObjective = "Highlord Darion Mograine wants you to use Shadow's Edge to slay 50 of the Lich King's minions in Icecrown Citadel. Souls can be obtained in 10 or 25 person difficulty.", completion = "<Highlord Mograine eyes you in silence for a moment.>\n\nYou seem to have endured this leg of your trial admirably, {race}.\n\nPray that fate continues to smile upon you in your endeavor...", sourceObjectiveStatus = "unverified-source-field" }
quests[24548] = { id = 24548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Splintered Throne", description = "The Lich King's throne once served as his prison. Kil'jaeden himself crafted the vessel of icy crystals from the twisting nether, its sole purpose to hold Ner'zhul's vengeful spirit.\n\nWhen Arthas struck the crystal with Frostmourne, he released Ner'zhul's soul, allowing it to merge with his own. Splinters from that impact are now scattered throughout the citadel.\n\nI shall require those shards, held only by the Lich King's most powerful servants, to seal the power contained in your blade.", sourceObjective = "Highlord Darion Mograine wants you to collect 50 Shadowfrost Shards.\n\nShadowfrost Shards may only be obtained in the 25 person difficulty setting.", progress = "Have you obtained the shards of the frozen throne, {class}?", completion = "These should suffice, {class}.\n\nSpeak to me when Shadow's Edge has been thoroughly empowered and I will attempt its completion.", sourceObjectiveStatus = "unverified-source-field" }
quests[24549] = { id = 24549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowmourne...", sourceObjective = "Highlord Darion Mograine wants you to bring him Shadow's Edge.", completion = "Congratulations, {class}.\n\nAgainst insurmountable odds, you have weathered the storm.\n\nI trust that you shall find your reward proportionate to your conviction...", sourceObjectiveStatus = "unverified-source-field" }
quests[24550] = { id = 24550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey into Thunder Bluff", description = "The wells are cleansed, and Mulgore's waters run sweet and clear once more. You've saved us...but you've also uncovered grim happenings. The actions of the Grimtotem must be made known.\n\nIt is time for you to enter Thunder Bluff, our great city atop the mesa.  Go to our leader, Baine Bloodhoof, son of Cairne. He must hear of this.", sourceObjective = "Speak with Baine Bloodhoof in Thunder Bluff.", completion = "Welcome to Thunder Bluff, {name}. You've done great things for our people.\n\nTell me of your journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[24551] = { id = 24551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the New Boss", description = "Our defense of the Barrens hasn't gone well under Gar'dul's command, {name}. Garrosh has sent Warlord Bloodhilt here to take control of the situation. He's here in camp, and if you want to make a good impression, you'll demonstrate some initiative.\n\nHead east into the Fields of Blood and seek out Northwatch recon units. Bringing the new Warlord a stack of their merit badges will help you make a name for yourself!", sourceObjective = "Kill Northwatch Recon patrols and collect 10 Theramore Merit Badges.", progress = "You look like the type of {class} who gets things done. What news do you have from the field?", completion = "<Bloodhilt looks at the badges, then allows them to spill from his hands onto the sands below. His lips curl open into a toothy grin.>\n\nNow THIS is what I like to see, {class}! What is your name again?\n\nYou will go far here.", sourceObjectiveStatus = "unverified-source-field" }
quests[24552] = { id = 24552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lion's Pride", description = "If you seek vengeance on our Alliance invaders, you would do well to observe the fiercest of predators in the Barrens.\n\nThe lions that stalk amongst the tall grass do so with cunning, stealth, and power. Learn from their example and you will understand the kind of war we need to fight.\n\nHunt the plains prowlers and pridemanes, then return to me to discuss what you have learned. You will often find them in the shade of large trees.", sourceObjective = "Kill any combination of 5 Plains Prowlers or Plains Pridemanes.", completion = "Ah yes... I see a cunning in your eyes that was not present before. Well done, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24553] = { id = 24553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purification of Quel'Delar", description = "I admit, I was skeptical that you had actually re-forged Quel'Delar and I did not expect Thalorien's spirit to reveal itself to you. You cannot understand what it means to me and to the rest of my people that Quel'Delar has been recovered.\n\nAs promised, I will admit you to the Sunwell and you will find the leaders of Silvermoon within. Carry the sword to the chamber of the Sunwell and immerse it. The blade will bond to you. When that happens, carry it to Caladis Brightspear at Quel'Delar's Rest.", sourceObjective = "Immerse your Tempered Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "What happened during your time in the Sunwell?", completion = "This is unbelievable, {name}. You've really done it! All of the quel'dorei have heard of Thalorien Dawnseeker and Quel'Delar, but no one ever thought the sword would be restored.", sourceObjectiveStatus = "unverified-source-field" }
quests[24554] = { id = 24554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battered Hilt", description = "This battered old sword hilt has seen better days. Before the hilt was snapped from the blade, it must've been a magnificent example of the blacksmith's art.\n\nThe graceful symbols and exotic gemstones decorating the hilt suggest that the weapon may have belonged to a powerful person. Surely, the Sunreavers would be interested in hearing about the recovery of such an artifact. Seek out their representatives at Quel'Delar's Rest, to the south of the Argent Tournament Grounds.", sourceObjective = "Bring the Battered Hilt to Myralion Sunblaze at Quel'Delar's Rest, south of the Argent Tournament Grounds.", progress = "What have you discovered?", completion = "<Myralion takes the hilt from you and scrutinizes the artifact.>\n\nThis came from the citadel? What was it doing there? This blade is certainly not of Scourge manufacture.\n\nWeapons of this quality can only be crafted by a few of Azeroth's creatures. We will have to consult them and see if they can help us identify it.", sourceObjectiveStatus = "unverified-source-field" }
quests[24555] = { id = 24555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What The Dragons Know", description = "There's no mistaking it - this hilt comes from a powerful, ancient weapon, but which one? I do not recognize these particular markings, but we haven't hit a dead end yet.\n\nKorialstrasz, better known as Krasus, has long been a friend to the quel'dorei and the Kirin Tor. With his vast knowledge and resources, he's certain to know something. Travel to the top of Wyrmrest Temple and seek his counsel, then report to Magister Hathorel inside Sunreaver's Sanctuary in Dalaran.", sourceObjective = "Speak to Krasus at the top of Wyrmrest Temple.", completion = "We must recover that book from the Silver Covenant. Without that book from Krasus, we stand little chance of solving the mystery of the sword in Icecrown or unlocking its power.", sourceObjectiveStatus = "unverified-source-field" }
quests[24556] = { id = 24556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Suitable Disguise", description = "Getting you inside the Silver Enclave will be tougher than it appears. Only those who possess Silver Covenant tabards are permitted entry to sanctuary. If we can get our hands on one, a simple enchantment will do the rest of the work.\n\nOn the balcony above Threads of Fate, you'll find Shandy Glossgleam. I've helped him a few times in the past, so he owes me a favor. He handles laundry for a wide variety of people in the city. Maybe he can find a way to 'lend' you a tabard for a while.", sourceObjective = "Obtain a Borrowed Tabard from Shandy Glossgleam.", progress = "Was Shandy able to help you get a Silver Covenant tabard?", completion = "I knew Shandy would find a way to make it work. Let me get this enchanted and ready for you to use. With any luck, the tabard's owner won't even know it's missing and Shandy will cover the rest of our tracks.", sourceObjectiveStatus = "unverified-source-field" }
quests[24557] = { id = 24557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Silver Covenant's Scheme", description = "One of my contacts in the Underbelly caught sight of a Silver Covenant agent gathering information at the Cantrips and Crows Tavern. Silver Covenant members aren't normally found in the sewers, so they must be plotting something.\n\nGo into the Underbelly, find this Silver Covenant agent, and eliminate him. Search the body for any information that might give us a lead on the location of that tome from Wyrmrest. We can't let those simpering Silver Covenant weaklings get it back to Icecrown before we do.", sourceObjective = "Capture the Silver Covenant Orders.", progress = "Did you find anything of use on that agent?", completion = "<Magister Hathorel reads the captured orders.>\n\nThe agent you intercepted was supposed to deliver the Wyrmrest tome to Icecrown, after meeting with one Arcanist Tybalin inside the Silver Enclave. We have to reclaim that book, {name}, and we only have one chance before it leaves the city. We have to work quickly.", sourceObjectiveStatus = "unverified-source-field" }
quests[24558] = { id = 24558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return To Myralion Sunblaze", description = "We must get this book to Myralion Sunblade. Would you bring it to him? I cannot rely on anyone else to transport the book and you have proven adept at evading the Silver Covenant's men.\n\nTake it with you to Quel'Delar's Rest, south of the Argent Tournament Grounds in Icecrown. Myralion will be waiting for you. If he can identify that blade, we may be able to claim it in the name of Aethas Sunreaver and show Dalaran and the Alliance that we will lead the charge against the Lich King.", sourceObjective = "Bring Ancient Dragonforged Blades to Myralion Sunblaze at Quel'Delar's Rest.", progress = "We've been expecting your return. What has kept you?", completion = "<Myralion accepts the heavy book and begins leafing through it.>\n\nThose symbols on the blade seemed familiar and now there's little wonder why. This is certainly a dragon blade, gifted to one of the mortal races, but which blade is this, and how did it come to rest in Icecrown?", sourceObjectiveStatus = "unverified-source-field" }
quests[24559] = { id = 24559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reforging The Sword", description = "We cannot allow Quel'Delar to remain broken and disgraced. Take the remnants of the sword, along with the battered hilt you discovered, and venture into the Pit of Saron within Icecrown Citadel.\n\nIn the pit, the Lich King uses slaves to mine, process, and transform saronite ore. This infused saronite is what we will use to rebuild Quel'Delar.\n\nYou must gather bars of infused saronite and capture the forgemaster's hammer, then bring them to the forgemaster's anvil and reforge the sword.", sourceObjective = "Obtain 5 Infused Saronite Bars and the Forgemaster's Hammer, then combine them with the Remnants of Quel'Delar to create the Reforged Quel'Delar.", progress = "Were you able to reconstruct Quel'Delar?", completion = "You have remade the blade of Quel'Delar in defiance of that Blood-Queen Lana'thel's pronouncement! Now, the blade must be tempered before we can show her the folly of her words.", sourceObjectiveStatus = "unverified-source-field" }
quests[24560] = { id = 24560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempering The Blade", description = "At last, the pieces of Quel'Delar are rejoined and the blade is whole, but it cannot see battle until you have tempered it. That jagged saronite edge is brittle and will shatter the moment it strikes anything.\n\nDeep in Icecrown Citadel's Forge of Souls is a place where the blade can safely be tempered. Take Quel'Delar with you to the abode of the Devourer of Souls and look for the crucible. Plunge the blade into the crucible to temper it and bring it back to me. I'll be waiting in The Frozen Halls.", sourceObjective = "Temper the Re-forged Quel'Delar in the Crucible of Souls.", progress = "Until the sword is tempered, it will be useless.", completion = "Tempering the sword should've restored the blade. Why hasn't it worked?", sourceObjectiveStatus = "unverified-source-field" }
quests[24561] = { id = 24561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Halls Of Reflection", description = "You have re-forged and tempered the sword, yet it sits quietly in its sheath, little different from a mundane blade. You say the sword pulls you, as though it possesses a will?\n\nDare you bring it where it wishes to go? It is not right that the sword should be this silent and this insistent, yet I fear that if you do not take the sword to its destination, we will never learn why. Bear it with you to Icecrown Citadel's Halls of Reflection, but be on your guard. I will wait for you in The Frozen Halls.", sourceObjective = "Bring Quel'Delar to Sword's Rest inside the Halls of Reflection.", progress = "What happened inside the Halls of Reflection?", completion = "How can evil take root in such a sword? I would not have thought it possible if the evidence wasn't here before my eyes. If the greatest of dragonkind's creations could be corrupted and turned against them, why not a mere sword?\n\nI believe Uther is right. You must heed his advice quickly, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24562] = { id = 24562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey To The Sunwell", description = "Take Quel'Delar to the Sunwell as quickly as possible, {name}. Trust in Uther's words when he says that you will not always be able to control the blade while it is subject to the evil of the Lich King's influence. You must travel to the Isle of Quel'Danas, and there, seek entry to the Sunwell itself, where you can cleanse the sword.\n\nThe guardians will try to stop you from entering the Sunwell Plateau, but make yourself known to Halduron Brightwing, who will be inspecting the guards there.", sourceObjective = "Speak with Halduron Brightwing at the entrance to the Sunwell Plateau on the Isle of Quel'Danas.", progress = "What brings you here?", completion = "I hope you understand that I can't just admit you to the Sunwell, {name}. This is the most sacred place known to the sin'dorei and we have only recently regained control over it.\n\nYou would raise the hopes of our people with tales of Quel'Delar? Without proof of the truth of your claims, I see no reason to take you at your word.", sourceObjectiveStatus = "unverified-source-field" }
quests[24563] = { id = 24563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thalorien Dawnseeker", description = "You are the one working with Myralion Sunblaze, arent you? I know of a way we can test the sword.\n\nIf you know the blade's history, you recall that it was borne by Thalorien Dawnseeker in defense of the Sunwell against the Scourge. He fell in what is now the Dead Scar, buying time for his men to make their own preparations. You will find his remains near the southern end of the Dead Scar on this isle. Visit them, and if his spirit gives you its blessing, I will allow you to enter the Sunwell.", sourceObjective = "Visit Thalorien Dawnseeker's Remains and obtain his blessing to wield Quel'Delar.", progress = "Did you visit the ground where Thalorien fell defending the Sunwell?", completion = "You truly do carry Quel'Delar. This is a great day for all of Quel'Thalas and the sin'dorei. You have my leave to enter the Sunwell and finish the sword's restoration. Keep your head high, {name}. The children of Silvermoon have dreamt of this day for years.", sourceObjectiveStatus = "unverified-source-field" }
quests[24564] = { id = 24564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purification of Quel'Delar", description = "The Sunwell and the end of Quel'Delar's exile await, {name}.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell. Immerse the reformed Quel'Delar in the Sunwell to complete the restoration. Afterward, show the blade to Myralion Sunblaze at Quel'Delar's Rest.", sourceObjective = "Immerse your Tempered Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "What happened inside the Sunwell?", completion = "Am I truly laying my eyes upon the weapon of Thalorien Dawnseeker? This is a wondrous day for the Sunreavers and for all sin'dorei!", sourceObjectiveStatus = "unverified-source-field" }
quests[24565] = { id = 24565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Biological Intervention", description = "The energies unleashed here have surged through the wildlife, twisting them into powerful and unstable forms. If allowed to spread beyond this grove, these deviates will wreak havoc on the existing ecosystem, devouring local prey and driving out the weaker natural creatures.\n\nYou must go and cull the population of the overgrowth. Return when this task is done.", sourceObjective = "Kill 5 Deviate Terrortooths and 5 Deviate Plainstriders.", completion = "Thank you, {name}. I'm pleased to see you return intact; the viciousness I've been seeing among these creatures is startling.", sourceObjectiveStatus = "unverified-source-field" }
quests[24566] = { id = 24566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sowing a Solution", description = "Based on what you've brought me, I think we may have a solution. I've imbued the lashvine seeds with healing energies.\n\nSimple contact with these should imbue the creatures here with enough energy to force out the corrupted influence.\n\nGo and attempt to heal the mutated raptors and plainstriders by sprinkling the seeds on them, and report the results back to me.", sourceObjective = "Use Soothing Seeds on 6 Deviate Terrortooths or Deviate Plainstriders and observe the results.", completion = "Oh dear. It seems the forces at work here are a bit difficult to control...\n\nPlease, don't bother Naralex with this. It will only upset him.", sourceObjectiveStatus = "unverified-source-field" }
quests[24567] = { id = 24567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report for Tryouts", description = "{name}, Coach Crosscheck is looking for you. He's the leader of our fearless footbomb team, the Bilgewater Buccaneers.\n\nHe says that the division title against the Steamwheedle Sharks is on the line and that you're the only one that can bring it home for us!\n\nHead west into town. You can't miss Kajaro Field.\n\nA footbomb star. This is going to be great for your image!", sourceObjective = "Speak with Coach Crosscheck at Kajaro Field on Kezan.", completion = "There you are, my boy! Quick, there's no time to waste! We need to get one of these shredders back in working order.\n\nI'm bringing you off the bench... you're going to win the game and the title for us!", sourceObjectiveStatus = "unverified-source-field" }
quests[24568] = { id = 24568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Walls!", description = "{name}, they're massing at the gates! The Alliance is trying to push their way into Mulgore, using footsoldiers to overwhelm the guards.\n\nWe have so little with which to defend the walls. We've kept pots of water boiling to repel the attackers until help arrives... Those will have to do.\n\nBut we need someone to coordinate our defenses. Say the word and I can give you an eagle-eye view of the battlefield.\n\nWe need you, {name}!", sourceObjective = "Speak with Winnoa Pineforest at the Fields of Blood in order to defend the gates of Mulgore from attack.", sourceObjectiveStatus = "unverified-source-field" }
quests[24569] = { id = 24569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegebreaker", description = "{name}, you've proven yourself on the Fields of Blood. But the Alliance still threatens our tauren friends.\n\nThe siege machinery outside the gates of Mulgore is like a spear aimed at our heart. I want you to go to the gates, south of here, and remove those siege vehicles from play.\n\nHere, use these stickybombs. They're courtesy of our new goblin allies. It looks as though they stuffed explosive powder into ... what looks like ... grease-covered socks. But they'll do.", sourceObjective = "Destroy 4 Northwatch Siege Engines at the Mulgore Gates.", progress = "Why did Gar'dul allow the Alliance to create such a buildup of heavy siege vehicles? Why wasn't a strike ordered until I got here? Gar'dul will have to answer for this...", completion = "Very good. Now, should they storm the gates, they will have to do so with infantry.\n\nDo you think they have the stomach for that?", sourceObjectiveStatus = "unverified-source-field" }
quests[24570] = { id = 24570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adder Subtraction", description = "The corruption unleashed here must be studied if we're to find a way of properly fighting it.\n\nLuckily, not all the creatures have been as altered as others. The smaller snakes drink little water, and do not eat plants, so their exposure to the energies here has been minimal. They've still absorbed enough to change coloration.\n\nGo collect these snakes from the overgrowth and return them to me, so we can see just what is happening to the creatures here.", sourceObjective = "Collect 5 Enervated Adders.", progress = "Have you collected enough? We'll need several for proper comparison.", completion = "These will do perfectly. Bright colors like these don't occur naturally in the barrens, but they haven't developed any other mutations so far.", sourceObjectiveStatus = "unverified-source-field" }
quests[24571] = { id = 24571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lashvine Seeds", description = "There's got to be a way to cure these poor creatures without having to take their lives. I have an idea, but I'll need your help, {class}.\n\nThe lashvine plants that roam here hold seeds full of the primal energy of this place. Collect these for me and bring them back, and we'll see if something can be done.", sourceObjective = "Collect 4 Writhing Seeds from Lashvines.", progress = "Do you have the seeds?", completion = "I'm concerned by how...active these are. Nevertheless, it simply means we must continue to act quickly before the corruption here becomes worse.", sourceObjectiveStatus = "unverified-source-field" }
quests[24572] = { id = 24572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Back Taurajo", description = "Outstanding work at the gates, {name}! The main body of the Alliance force is in general retreat. But I'm not satisfied.\n\nThey sacked Taurajo, which was little more than a hunters' camp. This 'Alliance' is unmasked at last for what it really is: A renegade band of butchers.\n\nEven now a group of humans linger behind to pick at the bones of smouldering Taurajo.\n\n<Bloodhilt hurls an axe into the dirt.>\n\nMake them suffer.", sourceObjective = "Kill 8 Taurajo Looters in the ruins of Taurajo.", completion = "Excellent. I'll have their bodies strung up along the gold road as a message to the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[24573] = { id = 24573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honoring the Dead", description = "With the immediate threat gone, can you help with some grim business?\n\nWe tauren do not bury our dead, we prepare the body for its return to the elements and place it at our sacred grave sites. Those killed in the Taurajo massacre have had no funeral, and I worry misguided Alliance soldiers will burn the bodies of the dead before the proper rites have been performed.\n\n{name}, please take this totem to Taurajo and perform services for Krulmoo, Dranh, Yonada, and Omusa. They ... didn't make it out of there.", sourceObjective = "Use the Funerary Totem on the corpses of Krulmoo, Dranh, Yonada, and Omusa in the ruins of Taurajo.", progress = "Have their spirits found peace with the Earthmother?", completion = "<Winnoa bows her head.>\n\nThank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[24574] = { id = 24574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Harvest Chaos", description = "If I have truly sown chaos, it is time for reaping.\n\nThe lumbering outgrowths of plant life shamble through the imbued stream here, {name}. They are a direct manifestation of the unstable forces mutating this area. Slay as many as you can, and we might be able to slow the spread of the overgrowth further.\n\nAnd while you're at it...be on the lookout for parts of them that appear especially corrupted. Bring any such pieces to me.", sourceObjective = "Kill 5 Outgrowths and find a Squirming Heart.", progress = "Cutting down the outgrowth will merely buy us some time. Have you found any suspicious pieces?", completion = "<Naralex slowly takes the squirming heart from you, visibly disturbed.>\n\nI've been a fool. The one truth I did not want to accept has been staring me in the face this entire time...this foul thing is proof of that.\n\nYou and I have much work to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[24575] = { id = 24575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liberation Day", description = "We recently found out that the villagers at Emberstone survived most of the ravages of the Curse.\n\nUnfortunately their village wasn't as fortunate when it came to the Forsaken invasion.\n\nThe Forsaken have taken the villagers prisoner and are forcing them to work the nearby mine as slaves.", sourceObjective = "Free 5 Enslaved Villagers inside the Emberstone Mine.", progress = "Have you freed the villagers, {name}?  I cannot imagine what duress they're enduring under the Forsaken.", completion = "You've done it again, {name}.  The freed villagers are eager to help us against the Forsaken in any way they can.", sourceObjectiveStatus = "unverified-source-field" }
quests[24576] = { id = 24576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Friendly Chat...", description = "<Roka listens with disgust as you tell her why you're trying to track down Snivel.>\n\nYou mean I've been under the spell of an alchemist all this time? I can't believe I fell for that fraud! If I ever get my hands on that conniving little goblin, I'll tear him apart!\n\nIf he's finished his errands, he's on his way down to the zeppelin tower in the middle of Orgrimmar! Whatever you do, {name}, you can't let him board that zeppelin and get away with all this!\n\nHurry to the zeppelin tower before you miss him!", sourceObjective = "Go to the zeppelin tower on the central bluff in  Orgrimmar and question Snivel Rustrocket about the supplies. Return with any evidence he gives you.", progress = "Did you find the guy, or did he crawl under a rock?", completion = "You got his ledger? Really? That's great, {name}. There's probably loads of good information in here.", sourceObjectiveStatus = "unverified-source-field" }
quests[24577] = { id = 24577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desolation Hold Inspection", description = "Thanks to you, the immediate threat is over. But my work here in the Barrens is only beginning.\n\nHonor's Stand was captured and Taurajo was sacked while Warlord Gar'dul was in charge of the region. The Warchief has sent me here to clean up his mess.\n\nI would like you to ride into Desolation Hold to the south in advance of me and let Gar'dul know that it is time for a reckoning.\n\nTalk to me when you are ready to leave and I will assemble my vanguard to accompany you.", sourceObjective = "Talk to Warlord Bloodhilt, then ride into Desolation Hold and inform Gar'dul that Warlord Bloodhilt is on his way.", completion = "<Gar'dul breaks into a sweat.>\n\nLook - ah - let's not discuss this here, in front of the men...", sourceObjectiveStatus = "unverified-source-field" }
quests[24578] = { id = 24578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blackwald", description = "It took a while, but I think I've put together what happened here.  At least partially.\n\nThere were survivors of the Curse in this town.  They joined others in the mountains, in Tempest's Reach.\n\nEveryone left, except the man who kept the journal, old man Bradshaw.  He noticed that the worgen attacks had stopped all of a sudden and decided to venture into the Blackwald.\n\nThere is an abandoned mill just northeast of town, it was where Bradshaw lived.  See if you can find any clues there.", sourceObjective = "Investigate the Bradshaw mill just outside Stormglen Village.", completion = "I've been expecting you, {name}.  Do not be alarmed.\n\nMy name is Belysra.  I am a priestess of the moon... a night elf.\n\nYou might not know my people, but the destinies of our two races have been linked since the Curse befell you.", sourceObjectiveStatus = "unverified-source-field" }
quests[24579] = { id = 24579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sartharion Must Die!", description = "Sartharion, the Onyx Guardian, watches over the eggs of the Twilight Dragonflight. He rests within the Obsidian Sanctum in the Chamber of the Aspects underneath Wyrmrest Temple.\n\nThe Council of Six has decreed that Sartharion must die!", sourceObjective = "Kill Sartharion.\n\nThis quest can be completed with any difficulty or size raid.", progress = "Sartharion yet breathes, {class}.", completion = "With Sartharion slain, surely Deathwing and Sinestra's plans are now stalled.", sourceObjectiveStatus = "unverified-source-field" }
quests[24580] = { id = 24580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anub'Rekhan Must Die!", description = "Anub'Rekhan, once-mighty Spider Lord of the nerubian empire, has been taken by the Lich King and corrupted into a state of undeath.\n\nNow a crypt lord, he sits in his parlor in the Arachnid Quarter of Naxxramas, spinning strategies for Kel'Thuzad.\n\nThe Council of Six has decreed that Anub'Rekhan must die!", sourceObjective = "Kill Anub'Rekhan.\n\nThis quest can be completed with any difficulty or size raid.", progress = "I've heard nothing of the destruction of Anub'Rekhan. Perhaps you should redouble your efforts?", completion = "Word of your success precedes you, {class}. Anub'Rekhan is no more. You did him a great service, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24581] = { id = 24581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noth the Plaguebringer Must Die!", description = "Noth the Plaguebringer, traitor and coward! Second only to the Lich King himself for the number of souls that have been Scourged!\n\nMake haste to Naxxramas. You will find him within the Plague Quarter hiding behind his undead minions.\n\nDestroy him! The Council of Six has decreed that Noth must die!", sourceObjective = "Kill Noth the Plaguebringer.\n\nThis quest can be completed with any difficulty or size raid.", progress = "Noth yet walks Naxxramas, {class}.", completion = "That's one less thorn in our side. With Noth destroyed, Scourge research into refining the means of creating the undead will grind to a halt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24582] = { id = 24582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instructor Razuvious Must Die!", description = "Instructor Razuvious smugly struts about the Military Quarter of Naxxramas. It is said that only a death knight personally trained by him could possibly even withstand the prowess of his blade.\n\nYou and your group are going to prove everyone wrong.\n\nThe Council of Six has decreed that Razuvious must die!", sourceObjective = "Kill Instructor Razuvious.\n\nThis quest can be completed with any difficulty or size raid.", completion = "Well done, {class}. The Scourge military command out of Naxxramas has been thrown into disarray by Razuvious's demise.", sourceObjectiveStatus = "unverified-source-field" }
quests[24583] = { id = 24583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patchwerk Must Die!", description = "The so-called \"avatar of war\", Patchwerk is the ultimate abomination. It is also taking a heavy toll upon on our forces in the Dragonblight.\n\nI want you to assemble your companions and enter the Construct Quarter of Naxxramas. Disassemble the construct.\n\nThe Council of Six has decreed that Patchwerk must die!", sourceObjective = "Kill Patchwerk.\n\nThis quest can be completed with any difficulty or size raid.", completion = "Children everywhere will sleep easier knowing that Patchwerk is no more.", sourceObjectiveStatus = "unverified-source-field" }
quests[24584] = { id = 24584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malygos Must Die!", description = "Our resources are strained. Malygos, the Spell-Weaver, is draining all of the magic out of the world, consolidating it in the Eye of Eternity. Without magic, we are doomed.\n\n{class}, the Nexus War must be brought to an end. The Council of Six has decreed that Malygos must die!", sourceObjective = "Kill Malygos.\n\nThis quest can be completed with any difficulty or size raid.", completion = "With Malygos defeated, the Nexus War should come to a swift conclusion. You have the gratitude of the Kirin Tor, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24585] = { id = 24585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flame Leviathan Must Die!", description = "Within the Formation Grounds sits Ulduar's first line of defense: Flame Leviathan.\n\nThe Kirin Tor have been provided with information suggesting that this Keeper-created machine is soon to be transported to an undisclosed location and let loose to wreak havoc upon the mortals of Azeroth.\n\nThis must not come to pass. The Council of Six has decreed that Flame Leviathan must die!", sourceObjective = "Kill Flame Leviathan.\n\nThis quest can be completed with any difficulty or size raid.", progress = "Why is Flame Leviathan not in pieces?", completion = "I never cease to be amazed by the horrors that can be created through the use of technology.", sourceObjectiveStatus = "unverified-source-field" }
quests[24586] = { id = 24586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Razorscale Must Die!", description = "Razorscale normally keeps to her aerie near the Colossal Forge in Ulduar. Of late, however, she has been spotted raining fire down upon lands outside of the titan complex.\n\nThough the broodmother's is a sad tale, she poses an imminent threat to all of Northrend. The Council of Six has decreed that Razorscale must die!", sourceObjective = "Kill Razorscale.\n\nThis quest can be completed with any difficulty or size raid.", progress = "Is something wrong? Why have you not yet dealt with Razorscale?", completion = "Now Veranus can finally rest in peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[24587] = { id = 24587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ignis the Furnace Master Must Die!", description = "The great fire giant, Ignis the Furnace Master toils away inside of Ulduar's Colossal Forge. Under orders from Loken, Ignis creates weapons that are terrifying in their power.\n\nThe Council of Six has decreed that Ignis must die!", sourceObjective = "Kill Ignis the Furnace Master.\n\nThis quest can be completed with any difficulty or size raid.", progress = "Ignis is not yet dead. The fire giant must fall!", completion = "I trust that you did not have to face too many of his iron construct assistants?", sourceObjectiveStatus = "unverified-source-field" }
quests[24588] = { id = 24588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "XT-002 Deconstructor Must Die!", description = "Yet another strange construct of Mimiron, the XT-002 Deconstructor actually thinks that it is the keeper's son. Do not be fooled by its feigned innocence. It is a deadly machine!\n\nYou will find the Deconstructor within Ulduar's Scrapyard. The Council of Six has decreed that XT-002 Deconstructor must die!", sourceObjective = "Kill XT-002 Deconstructor.\n\nThis quest can be completed with any difficulty or size raid.", progress = "I am given to understand that you have not yet been able to deconstruct the Deconstructor.", completion = "The greatest weakness of Ulduar is its masters' blind faith in their inventions to protect it.", sourceObjectiveStatus = "unverified-source-field" }
quests[24589] = { id = 24589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Jaraxxus Must Die!", description = "Archmage Timear has foreseen a horrible event, which is about to transpire. A foolish gnome warlock is about to accidentally summon an Eredar lord of the Burning Legion into the middle of the Trial of the Crusader.\n\nYou must be there when it happens, {class}. If Lord Jaraxxus escapes, he will open a portal and the Burning Legion will spill forth into our world once more.\n\nThe Council of Six has decreed that Lord Jaraxxus must die!", sourceObjective = "Kill Lord Jaraxxus.\n\nThis quest can be completed with any difficulty or size raid.", completion = "All of Azeroth is fortunate that Timear foresaw the Eredar lord's arrival and that you were there in time to slay him.", sourceObjectiveStatus = "unverified-source-field" }
quests[24590] = { id = 24590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Marrowgar Must Die!", description = "Lord Marrowgar is the guardian of the Frozen Throne within the Spire Chamber. Pieced together by the Lich King from the bones of a thousand vanquished adventurers, Marrowgar wields the power of the throne itself.\n\nWithout the destruction of this bone wraith, there is no hope of taking Icecrown Citadel.\n\nThe Council of Six has decreed that Lord Marrowgar must die!", sourceObjective = "Kill Lord Marrowgar.\n\nThis quest can be completed with any difficulty or size raid.", completion = "The Frozen Throne is without its chief guardian thanks to you. Our attacks upon the Lich King's forces will be all the more successful now.", sourceObjectiveStatus = "unverified-source-field" }
quests[24591] = { id = 24591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Changing of the Gar'dul", description = "When Bloodhilt arrives, I'd like to - ah - talk in private. Can you accompany me to make sure things stay on the level? This Bloodhilt is a, ah, he's a, he's a loose cannon.\n\n<Gar'dul tries to compose himself.>\n\nMeet me atop the northern tower and we'll talk with Bloodhilt together.You will be able to choose one of these rewards:", sourceObjective = "Go to the top of the northern tower in Desolation Hold and help Warlord Bloodhilt \"Relieve\" Gar'dul of command.", sourceObjectiveStatus = "unverified-source-field" }
quests[24592] = { id = 24592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betrayal at Tempest's Reach", description = "King Greymane has been taken prisoner by Lord Godfrey in Tempest's Reach!\n\nHe managed to convince two of the eastern lords to go with his plan.  The fool seems to think he can strike a deal with the Forsaken by turning Greymane over to them.\n\nListen carefully, {name}.  We need to resolve this with as little bloodshed as possible.\n\nThis potion will allow you to sneak in undetected.  We need you to assassinate the traitorous lords before this gets out of hand!", sourceObjective = "Drink Krennan's Potion of Stealth in Tempest's Reach and assassinate Baron Ashbury and Lord Walden.", progress = "Careful, {name}.", completion = "I wish it could've been avoided, {name}.  Let us ensure this is resolved without further bloodshed.", sourceObjectiveStatus = "unverified-source-field" }
quests[24593] = { id = 24593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neither Human Nor Beast", description = "It is time, {name}.  This... alchemy that has kept the beast inside you at bay will not last for long.\n\nThe first cursed worgen were night elf druids like our new allies.  They, however, abandoned the balance that the rest of their kind embraced and allowed the beast to take over their minds.\n\nIt is only fitting that their brethren be the ones that deliver us from the Curse.  Go, {class}.  Drink from the waters of Tal'doren and make peace with yourself.", sourceObjective = "Drink from the Well of Tranquility, the Well of Balance and the Well of Fury.", progress = "It is always good to see you brother.", completion = "It is done then, {name}.  You are one of us now.", sourceObjectiveStatus = "unverified-source-field" }
quests[24594] = { id = 24594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purification of Quel'Delar", description = "The Sunwell and the end of Quel'Delar's exile await, {name}.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary of them and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Speak to a Warden of the Sunwell to enter the Sunwell Plateau. Immerse the reformed Quel'Delar in the Sunwell to complete the restoration. Show the blade to Myralion Sunblaze at Quel'Delar's Rest once it is restored.", sourceObjective = "Immerse your Tainted Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "You have returned from the Sunwell?", completion = "Am I truly laying my eyes upon the weapon of Thalorien Dawnseeker? This is a wondrous day for the Sunreavers and for all sin'dorei!", sourceObjectiveStatus = "unverified-source-field" }
quests[24595] = { id = 24595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purification of Quel'Delar", description = "I admit, I was skeptical that you had actually re-forged Quel'Delar and I did not expect Thalorien's spirit to reveal itself to you. You cannot understand what it means to my people that Quel'Delar has been recovered.\n\nAs promised, I will admit you to the Sunwell and you will find the leaders of Silvermoon within. Carry the sword to the chamber of the Sunwell and immerse it. Once the blade is restored, return with it to Caladis Brightspear at Quel'Delar's Rest.", sourceObjective = "Immerse your Tainted Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "Tell me of what happened in the Sunwell, {name}.", completion = "This is unbelievable, {name}. You've really done it! All of the quel'dorei have heard of Thalorien Dawnseeker and Quel'Delar, but no one ever thought the sword would be restored.", sourceObjectiveStatus = "unverified-source-field" }
quests[24596] = { id = 24596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purification of Quel'Delar", description = "The Sunwell and the end of Quel'Delar's exile await, {name}.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary of them and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Immerse the reformed Quel'Delar in the Sunwell to complete the its restoration, then speak with Myralion Sunblaze at Quel'Delar's Rest. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", sourceObjective = "Immerse your Tainted Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "What happened during your visit to the Sunwell?", completion = "Am I truly laying my eyes upon the weapon of Thalorien Dawnseeker? This is a wondrous day for the Sunreavers and for all sin'dorei!", sourceObjectiveStatus = "unverified-source-field" }
quests[24597] = { id = 24597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for the King of Stormwind", description = "Did you want to make a Lovely Charm Bracelet for the king of Stormwind? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to King Varian Wrynn in Stormwind.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24598] = { id = 24598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purification of Quel'Delar", description = "The Sunwell and the end of Quel'Delar's exile await, {name}.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary of them and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Immerse the reformed Quel'Delar in the Sunwell to complete its restoration, then show it to Myralio Sunblaze at Quel'Delar's Rest. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", sourceObjective = "Immerse your Tempered Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "What news do you bring from the Sunwell?", completion = "Am I truly laying my eyes upon the weapon of Thalorien Dawnseeker? This is a wondrous day for the Sunreavers and for all sin'dorei!", sourceObjectiveStatus = "unverified-source-field" }
quests[24601] = { id = 24601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nightmare Scar", description = "This confirms it. The overgrowth here is not being caused by a mere overabundance of energy.\n\nDo you understand? This is beyond what happened at the Wailing Caverns now. A rift into the Nightmare must have torn open in the middle of the very land we're standing on! And to think it's my fault...\n\nI'm done picking at the edges of this wound. Go to the west, to the center of the overgrowth, and meet me again there. We will dive into the heart of this corruption and force it shut!", sourceObjective = "Help Naralex seal the Nightmare Scar.", progress = "We must not allow the nightmare to spread further into our world!", completion = "We've done it! The nightmare's connection to this place has been severed. The rest of the land is safe from this intrusion now, and in time, the abberations here will be subsumed by the balance of nature.\n\nI cannot thank you enough, {name}. By helping to restore order here, you've let me make amends for my foolish actions.", sourceObjectiveStatus = "unverified-source-field" }
quests[24602] = { id = 24602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laid to Rest", description = "In our hurried escape for safety, we disturbed the resting homes of our ancestors, {name}.  A grave sin, if you'll pardon the pun.\n\nIt is tradition that a small memento be buried on top of a Gilnean's graveyard, beneath the shallow earth.  The stampede of people fleeing these tunnels has unearthed these mementos and angered the spirits.\n\nFind them and bring them to me.  We'll see to it that the dead return to their eternal slumber.", sourceObjective = "Obtain 5 Unearthed Mementos.", progress = "You're back, {name}.", completion = "Thank you, {name}.  Let us hope this works.", sourceObjectiveStatus = "unverified-source-field" }
quests[24603] = { id = 24603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Stop Bereavin'", description = "For a moment, I thought my hatred had stilled. My wife laid to rest, a final offering of the blood of her murderers to quell her tortured spirit. I thought perhaps peace would appeal to me.\n\nI was wrong.\n\nI will not rest now until every single filthy, squealing, murderous quilboar lays dead and broken! I cannot kill them fast enough with my own two hands.  Go and slay more for me, {race}.", sourceObjective = "Kill 13 Razormane Quilboar.", completion = "Good. Take your reward; this is only a prelude.", sourceObjectiveStatus = "unverified-source-field" }
